            ? stateName
            : model.Namespace + "." + stateName;

        return new CommandFluxorModel(
            model.TypeName,
            model.Namespace,
            stateName,
            featureName,
            actionsWrapper,
            reducers,
            commandFqn,
            featureQualified);
    }
