using System.Reflection;

using Hexalith.FrontComposer.SourceTools;

using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

using Shouldly;

namespace Hexalith.FrontComposer.SourceTools.Tests.Architecture;

[Trait("Category", "Governance")]
public sealed class SourceToolsTypeOrganizationGovernanceTests {
    private const string DriftNamespace = "Hexalith.FrontComposer.SourceTools.Drift";
    private static readonly string[] TargetTypeNames = [
        "DriftConstants",
        "DriftOptionsResult",
        "DriftOptions",
        "DriftBaselineInput",
        "DriftBaselineLoadResult",
        "DriftBaselineSet",
        "DriftBaselineContract",
        "DriftBaselineProperty",
        "DriftBaselineLoader",
        "DriftCurrentContract",
        "DriftCurrentProperty",
        "DriftCurrentSnapshot",
        "DriftComparisonResult",
        "DriftComparisonService",
        "DriftDiagnosticFact",
        "DriftSanitizer",
        "DriftDiagnosticDescriptors",
    ];

    [Fact]
    public void ProductionSources_DirectDeclarations_UseOneSameNamedTypePerFile() {
        (string Path, string Content)[] sources = LoadProductionSources(LocateDriftRoot());

        List<string> violations = FindOrganizationViolations(sources);

        sources.Length.ShouldBe(17);
        violations.ShouldBeEmpty(
            "Drift production files must contain exactly one direct namespace/compilation-unit type or delegate "
            + "whose name matches the file. Violations: "
            + string.Join(", ", violations));
    }

    [Fact]
    public void OrganizationGuard_SyntheticMultiKindSource_ReportsPathAndNames() {
        (string Path, string Content)[] sources = [
            (
                "Synthetic/MultiType.cs",
                "namespace Hexalith.FrontComposer.SourceTools.Drift;\n"
                + "internal sealed class First { }\n"
                + "internal delegate void Second();\n"),
        ];

        List<string> violations = FindOrganizationViolations(sources);

        violations.Count.ShouldBe(1);
        violations[0].ShouldContain("Synthetic/MultiType.cs");
        violations[0].ShouldContain("First");
        violations[0].ShouldContain("Second");
    }

    [Fact]
    public void OrganizationGuard_SyntheticNameMismatchSource_ReportsFileAndDeclaration() {
        // A single declaration whose name does not match its file must be flagged. This
        // exercises the file-name parity branch, which the multi-kind sample above never
        // reaches (that one trips the declaration-count branch and short-circuits first).
        (string Path, string Content)[] sources = [
            (
                "Synthetic/Second.cs",
                "namespace Hexalith.FrontComposer.SourceTools.Drift;\n"
                + "internal sealed class First { }\n"),
        ];

        List<string> violations = FindOrganizationViolations(sources);

        violations.Count.ShouldBe(1);
        violations[0].ShouldContain("Synthetic/Second.cs");
        violations[0].ShouldContain("First");
        violations[0].ShouldContain("Second");
    }

    [Fact]
    [Trait("Category", "Contract")]
    public void TargetTypes_AfterMechanicalSplit_PreserveExactInternalTopLevelIdentity() {
        Assembly assembly = typeof(FrontComposerGenerator).Assembly;
        Type[] types = TargetTypeNames
            .Select(name => assembly.GetType(DriftNamespace + "." + name, throwOnError: true)!)
            .ToArray();

        // The pinned inventory is exhaustive: the Drift namespace must expose exactly these
        // 17 internal top-level types and no others, so a new unpinned type fails the guard.
        // (A bare types.Length check is tautological — Select preserves the source count.)
        TargetTypeNames.Length.ShouldBe(17);
        assembly.GetTypes()
            .Where(candidate => string.Equals(candidate.Namespace, DriftNamespace, StringComparison.Ordinal)
                && !candidate.IsNested)
            .Select(candidate => candidate.Name)
            .OrderBy(name => name, StringComparer.Ordinal)
            .ShouldBe(TargetTypeNames.OrderBy(name => name, StringComparer.Ordinal));

        foreach (Type type in types) {
            type.Namespace.ShouldBe(DriftNamespace);
            type.DeclaringType.ShouldBeNull();
            type.IsNested.ShouldBeFalse();
            type.IsPublic.ShouldBeFalse();
            type.IsNotPublic.ShouldBeTrue();
            type.IsClass.ShouldBeTrue();
            type.IsSealed.ShouldBeTrue();
        }

        types.Count(type => type.IsAbstract).ShouldBe(4);
        types.Count(type => !type.IsAbstract).ShouldBe(13);

        Type baselineInput = types.Single(type => type.Name == "DriftBaselineInput");
        baselineInput.GetInterfaces().ShouldContain(typeof(IEquatable<>).MakeGenericType(baselineInput));

        Type comparisonService = types.Single(type => type.Name == "DriftComparisonService");
        comparisonService.IsSealed.ShouldBeTrue();
        comparisonService.IsAbstract.ShouldBeFalse();
    }

    [Fact]
    [Trait("Category", "Contract")]
    public void DriftNamespace_AfterMechanicalSplit_ExportsNoPublicTypes() {
        Assembly assembly = typeof(FrontComposerGenerator).Assembly;

        Type[] exportedDriftTypes = assembly.GetExportedTypes()
            .Where(type => string.Equals(type.Namespace, DriftNamespace, StringComparison.Ordinal))
            .ToArray();

        exportedDriftTypes.ShouldBeEmpty();
    }

    private static List<string> FindOrganizationViolations(
        IEnumerable<(string Path, string Content)> sources) {
        List<string> violations = [];

        foreach ((string path, string content) in sources) {
            MemberDeclarationSyntax[] declarations = GetDirectTopLevelDeclarations(content);
            if (declarations.Length != 1) {
                violations.Add($"{path}: expected one declaration; found {declarations.Length} ({string.Join(", ", declarations.Select(GetDeclarationName))})");
                continue;
            }

            string declarationName = GetDeclarationName(declarations[0]);
            string fileName = Path.GetFileNameWithoutExtension(path);
            if (!string.Equals(declarationName, fileName, StringComparison.Ordinal)) {
                violations.Add($"{path}: declaration {declarationName} does not match file {fileName}");
            }
        }

        return violations;
    }

    private static MemberDeclarationSyntax[] GetDirectTopLevelDeclarations(string source) {
        CompilationUnitSyntax root = CSharpSyntaxTree.ParseText(source).GetCompilationUnitRoot();
        return root.Members
            .SelectMany(member => member is BaseNamespaceDeclarationSyntax namespaceDeclaration
                ? namespaceDeclaration.Members
                : [member])
            .Where(member => member is BaseTypeDeclarationSyntax or DelegateDeclarationSyntax)
            .ToArray();
    }

    private static string GetDeclarationName(MemberDeclarationSyntax declaration)
        => declaration switch {
            BaseTypeDeclarationSyntax type => type.Identifier.ValueText,
            DelegateDeclarationSyntax @delegate => @delegate.Identifier.ValueText,
            _ => throw new InvalidOperationException($"Unsupported declaration kind {declaration.Kind()}."),
        };

    private static (string Path, string Content)[] LoadProductionSources(string driftRoot) => [
        .. Directory.EnumerateFiles(driftRoot, "*.cs", SearchOption.AllDirectories)
            .Select(path => new {
                FullPath = path,
                RelativePath = Normalize(Path.GetRelativePath(driftRoot, path)),
            })
            .Where(file => !IsBuildOrGeneratedPath(file.RelativePath))
            .OrderBy(file => file.RelativePath, StringComparer.Ordinal)
            .Select(file => (file.RelativePath, File.ReadAllText(file.FullPath))),
    ];

    private static bool IsBuildOrGeneratedPath(string relativePath) {
        string[] segments = relativePath.Split('/');
        return segments.Any(segment => segment.Equals("bin", StringComparison.OrdinalIgnoreCase)
            || segment.Equals("obj", StringComparison.OrdinalIgnoreCase)
            || segment.Equals("generated", StringComparison.OrdinalIgnoreCase));
    }

    private static string LocateDriftRoot() {
        DirectoryInfo? directory = new(AppContext.BaseDirectory);
        while (directory is not null) {
            string candidate = Path.Combine(
                directory.FullName,
                "src",
                "Hexalith.FrontComposer.SourceTools",
                "Drift");
            if (Directory.Exists(candidate)) {
                return candidate;
            }

            directory = directory.Parent;
        }

        throw new DirectoryNotFoundException(
            "Could not locate src/Hexalith.FrontComposer.SourceTools/Drift.");
    }

    private static string Normalize(string path) => path.Replace('\\', '/');
}

using System.Diagnostics;
using System.Text;

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

using Shouldly;

using static Hexalith.FrontComposer.SourceTools.Tests.Drift.Comparison.DriftClassifierProjectionPropertyTests;

namespace Hexalith.FrontComposer.SourceTools.Tests.Benchmarks;

/// <summary>
/// AC11 / T7 — NFR8: median incremental added overhead for drift detection on a representative
/// bounded fixture must remain &lt; 500 ms. Warmup excluded, ≥ 20 measured iterations, median
/// and p95 reported for both cache-hit and cache-miss paths. Sibling to
/// <c>IncrementalRebuildBenchmarkTests</c>; marked benchmark, not a unit gate.
/// </summary>
public sealed class DriftBenchmarkTests {
    private const int RepresentativeDeclarationCount = 25;
    private const int WarmupIterations = 5;
    private const int MeasuredIterations = 20;
    private const double Nfr8MedianBudgetMs = 500.0;

    [Fact]
    [Trait("Category", "Performance")]
    public void IncrementalRebuild_WithDriftDetection_StaysBelowNfr8MedianBudget_CacheHit() {
        (CSharpCompilation compilation, AdditionalText baseline) = BuildBoundedFixture(declarationCount: RepresentativeDeclarationCount);
        FrontComposerGenerator generator = new();

        // Prime: warm-up runs that do not contribute to measurement.
        GeneratorDriver primed = CSharpGeneratorDriver.Create(
            generators: [generator.AsSourceGenerator()],
            additionalTexts: [baseline],
            optionsProvider: CompilationHelper.DriftEnabledOptions());
        for (int i = 0; i < WarmupIterations; i++) {
            primed = primed.RunGenerators(compilation, TestContext.Current.CancellationToken);
        }

        // Measured: cache-hit path = re-run with identical inputs.
        double[] cacheHitMs = new double[MeasuredIterations];
        for (int i = 0; i < MeasuredIterations; i++) {
            var sw = Stopwatch.StartNew();
            primed = primed.RunGenerators(compilation, TestContext.Current.CancellationToken);
            sw.Stop();
            cacheHitMs[i] = sw.Elapsed.TotalMilliseconds;
        }

        Array.Sort(cacheHitMs);
        double medianMs = cacheHitMs[MeasuredIterations / 2];
        double p95Ms = cacheHitMs[(int)(MeasuredIterations * 0.95)];
        Console.WriteLine(string.Format(
            System.Globalization.CultureInfo.InvariantCulture,
            "DriftBenchmark cache-hit median={0:F3}ms p95={1:F3}ms",
            medianMs,
            p95Ms));

        medianMs.ShouldBeLessThan(Nfr8MedianBudgetMs,
            $"AC11 / NFR8 — median cache-hit incremental added overhead {medianMs:F1} ms exceeded {Nfr8MedianBudgetMs} ms budget.");
        p95Ms.ShouldBeLessThan(Nfr8MedianBudgetMs * 2.0,
            $"AC11 — p95 cache-hit overhead {p95Ms:F1} ms exceeded soft 2x budget.");
    }

    [Fact]
    [Trait("Category", "Performance")]
    public void IncrementalRebuild_WithDriftDetection_StaysBelowNfr8MedianBudget_CacheMiss() {
        FrontComposerGenerator generator = new();
        (CSharpCompilation baseCompilation, AdditionalText baseline) = BuildBoundedFixture(declarationCount: RepresentativeDeclarationCount);

        GeneratorDriver primed = CSharpGeneratorDriver.Create(
            generators: [generator.AsSourceGenerator()],
            additionalTexts: [baseline],
            optionsProvider: CompilationHelper.DriftEnabledOptions());
        for (int i = 0; i < WarmupIterations; i++) {
            CSharpCompilation warmupMutated = MutateOneDeclaration(baseCompilation, iteration: i);
            primed = primed.RunGenerators(warmupMutated, TestContext.Current.CancellationToken);
            primed = primed.RunGenerators(baseCompilation, TestContext.Current.CancellationToken);
        }

        double[] cacheMissMs = new double[MeasuredIterations];
        for (int i = 0; i < MeasuredIterations; i++) {
            // Cache-miss path = mutate ONE projection per iteration to trigger re-comparison.
            CSharpCompilation mutated = MutateOneDeclaration(baseCompilation, iteration: i);
            var sw = Stopwatch.StartNew();
            primed = primed.RunGenerators(mutated, TestContext.Current.CancellationToken);
            sw.Stop();
            cacheMissMs[i] = sw.Elapsed.TotalMilliseconds;
        }

        Array.Sort(cacheMissMs);
        double medianMs = cacheMissMs[MeasuredIterations / 2];
        double p95Ms = cacheMissMs[(int)(MeasuredIterations * 0.95)];
        Console.WriteLine(string.Format(
            System.Globalization.CultureInfo.InvariantCulture,
            "DriftBenchmark cache-miss median={0:F3}ms p95={1:F3}ms",
            medianMs,
            p95Ms));

        medianMs.ShouldBeLessThan(Nfr8MedianBudgetMs,
            $"AC11 / NFR8 — median cache-miss incremental added overhead {medianMs:F1} ms exceeded {Nfr8MedianBudgetMs} ms budget.");
        p95Ms.ShouldBeLessThan(Nfr8MedianBudgetMs * 2.0,
            $"AC11 — p95 cache-miss overhead {p95Ms:F1} ms exceeded soft 2x budget.");
    }

    private static (CSharpCompilation compilation, AdditionalText baseline) BuildBoundedFixture(int declarationCount) {
        StringBuilder source = new();
        _ = source.AppendLine("using Hexalith.FrontComposer.Contracts.Attributes;");
        _ = source.AppendLine("namespace TestDomain;");
        StringBuilder baselineSb = new();
        _ = baselineSb.AppendLine("{ \"schemaVersion\": \"frontcomposer.generated-ui-baseline.v1\", \"algorithm\": \"frontcomposer-structural-v1\", \"contracts\": [");

        for (int i = 0; i < declarationCount; i++) {
            _ = source.AppendFormat(System.Globalization.CultureInfo.InvariantCulture,
                "[BoundedContext(\"Orders\")] [Projection] public partial class P{0:D2} {{ public string Id {{ get; set; }} = string.Empty; public int Priority {{ get; set; }} }}{1}",
                i, Environment.NewLine);
            _ = baselineSb.AppendFormat(System.Globalization.CultureInfo.InvariantCulture,
                "{0}{{ \"family\": \"projection\", \"type\": \"TestDomain.P{1:D2}\", \"boundedContext\": \"Orders\", \"properties\": [{{ \"name\": \"Id\", \"category\": \"String\", \"nullable\": false }}, {{ \"name\": \"Priority\", \"category\": \"Int32\", \"nullable\": false }}] }}",
                i == 0 ? string.Empty : ",\n", i);
        }
        _ = baselineSb.AppendLine();
        _ = baselineSb.AppendLine("] }");

        CSharpCompilation compilation = CompilationHelper.CreateCompilation(source.ToString());
        AdditionalText baseline = new InMemoryAdditionalText("frontcomposer.drift-baseline.json", baselineSb.ToString());
        return (compilation, baseline);
    }

    private static CSharpCompilation MutateOneDeclaration(CSharpCompilation compilation, int iteration) {
        SyntaxTree existing = compilation.SyntaxTrees.First();
        string source = existing.ToString();
        int declarationIndex = iteration % RepresentativeDeclarationCount;
        string target = string.Format(
            System.Globalization.CultureInfo.InvariantCulture,
            "public partial class P{0:D2} {{ public string Id {{ get; set; }} = string.Empty; public int Priority",
            declarationIndex);
        string replacement = string.Format(
            System.Globalization.CultureInfo.InvariantCulture,
            "public partial class P{0:D2} {{ public string Id {{ get; set; }} = string.Empty; public int? Priority",
            declarationIndex);
        string mutated = source.Replace(target, replacement, StringComparison.Ordinal);
        mutated.ShouldNotBe(
            source,
            "AC11 — cache-miss benchmark must mutate exactly one targeted declaration per iteration.");
        return compilation.ReplaceSyntaxTree(existing, CSharpSyntaxTree.ParseText(mutated));
    }
}

// Story 1.8 — Task 2: Incremental rebuild benchmark.
//
// Two-pass incremental protocol:
//   Pass 1: driver.RunGenerators(C1) — seeds the generator's incremental cache.
//   Pass 2: mutate the source to add ONE property to a [Projection] type,
//           build compilation C2 (by replacing the syntax tree), and time
//           ONLY driver.RunGenerators(C2). The delta is the incremental
//           rebuild cost.
//
// NFR8: incremental rebuild < 500 ms per domain assembly.
//
// Baseline machine spec (record when run locally / in CI):
//   - CPU: e.g., AMD Ryzen 9 / Intel i7 12th gen / GitHub Actions ubuntu-latest
//   - RAM: 16+ GB
//   - OS:  Windows 11 24H2 / ubuntu-latest / macOS 14
//   - .NET SDK: 10.0.x
// The local baseline captured when writing this test was:
//   < 100 ms for the incremental delta on a warm process. The 500 ms budget
//   is a CI-safe ceiling; any measurement above it should block the PR
//   once CI exits advisory mode.
//
// CI filtering: marked with [Trait("Category", "Performance")] so the perf
// bucket can be run / excluded independently. The class follows xUnit v3
// patterns (`TestContext.Current.CancellationToken`) per the Story 1.8
// Dev Notes ("xUnit v3 (3.2.2) with Verify.XunitV3 — use xUnit v3 patterns
// for all new tests").

using System.Collections.Immutable;
using System.Diagnostics;

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

using Shouldly;

namespace Hexalith.FrontComposer.SourceTools.Tests.Benchmarks;

[Trait("Category", "Performance")]
public class IncrementalRebuildBenchmarkTests {

    private const string _initialSource = @"
using Hexalith.FrontComposer.Contracts.Attributes;

namespace TestDomain;

[BoundedContext(""Counter"")]
[Projection]
[ProjectionRole(ProjectionRole.StatusOverview)]
public partial class CounterProjection
{
    public string Name { get; set; } = string.Empty;
    public int Count { get; set; }
    public bool IsActive { get; set; }
}";

    private const string _mutatedSource = @"
using Hexalith.FrontComposer.Contracts.Attributes;

namespace TestDomain;

[BoundedContext(""Counter"")]
[Projection]
[ProjectionRole(ProjectionRole.StatusOverview)]
public partial class CounterProjection
{
    public string Name { get; set; } = string.Empty;
    public int Count { get; set; }
    public bool IsActive { get; set; }
    public int AddedProperty { get; set; }
}";

    [Fact]
    public void IncrementalDeltaRebuild_AddOneProperty_CompletesUnder500ms() {
        // Measurement methodology (review-2 hardening):
        //   1 warmup iteration (not measured) absorbs JIT of the equality/diff
        //   paths on the first timed invocation. Then 5 sampled iterations; we
        //   assert on the MEDIAN elapsed time to suppress outlier noise from
        //   GC pauses or CI scheduler preemption. Single-shot stopwatch below
        //   a ~100 ms target is noise-dominated; the median is the reliable
        //   quantity to compare against the 500 ms NFR8 ceiling.
        const int warmupIterations = 1;
        const int sampleIterations = 5;

        CancellationToken ct = TestContext.Current.CancellationToken;

        CSharpCompilation compilation1 = CompilationHelper.CreateCompilation(_initialSource);
        FrontComposerGenerator generator = new();

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            [generator.AsSourceGenerator()],
            driverOptions: new GeneratorDriverOptions(
                disabledOutputs: IncrementalGeneratorOutputKind.None,
                trackIncrementalGeneratorSteps: true));

        // Pass 1: seed the incremental cache (not measured).
        driver = driver.RunGenerators(compilation1, ct);
        GeneratorDriverRunResult pass1Result = driver.GetRunResult();
        pass1Result.Diagnostics.Where(d => d.Severity == DiagnosticSeverity.Error).ShouldBeEmpty(
            "Initial generation must not produce errors before measuring the incremental delta.");

        // Mutate: replace the single syntax tree with the source containing one extra property.
        CSharpCompilation compilation2 = compilation1.ReplaceSyntaxTree(
            compilation1.SyntaxTrees.First(),
            CSharpSyntaxTree.ParseText(_mutatedSource, cancellationToken: ct));

        // Warmup: absorb JIT cost of the first delta-rebuild path. Not measured.
        GeneratorDriver warmupDriver = driver;
        for (int i = 0; i < warmupIterations; i++) {
            warmupDriver = warmupDriver.RunGenerators(compilation2, ct);
            // Re-seed with compilation1 so the next warmup iteration also observes a delta.
            warmupDriver = warmupDriver.RunGenerators(compilation1, ct);
        }

        // Sampled measurement: alternate compilation2 (the timed delta) with
        // compilation1 (re-seed so the next delta is real). Collect median.
        long[] samples = new long[sampleIterations];
        GeneratorDriverRunResult lastDeltaResult = null!;
        GeneratorDriver measureDriver = driver;
        // Re-seed once so the next RunGenerators(compilation2) is a real delta.
        measureDriver = measureDriver.RunGenerators(compilation1, ct);
        for (int i = 0; i < sampleIterations; i++) {
            var sw = Stopwatch.StartNew();
            measureDriver = measureDriver.RunGenerators(compilation2, ct);
            sw.Stop();
            samples[i] = sw.ElapsedMilliseconds;
            lastDeltaResult = measureDriver.GetRunResult();
            // Re-seed for the next iteration so it observes a Modified Parse delta.
            measureDriver = measureDriver.RunGenerators(compilation1, ct);
        }

        long medianMs = samples.OrderBy(x => x).ElementAt(sampleIterations / 2);

        lastDeltaResult.Diagnostics.Where(d => d.Severity == DiagnosticSeverity.Error).ShouldBeEmpty(
            "Incremental rebuild must not produce errors.");

        // Sanity: the Parse stage must have observed a modification (otherwise we didn't
        // actually measure a delta rebuild — the cache key may not reflect source changes).
        // Note: this asserts the cache is not *under-eager* (it does detect source change).
        // The inverse property — that unchanged source produces Unchanged — is covered by
        // IncrementalCachingTests.
        GeneratorRunResult result = lastDeltaResult.Results[0];
        result.TrackedSteps.ContainsKey("Parse").ShouldBeTrue(
            "The Parse stage must be tracked so the incremental contract can be verified.");
        result.TrackedSteps["Parse"]
            .SelectMany(s => s.Outputs)
            .Any(o => o.Reason == IncrementalStepRunReason.Modified)
            .ShouldBeTrue("Adding a property must cause the Parse stage to report Modified — otherwise the cache is under-eager.");

        medianMs.ShouldBeLessThan(
            500L,
            $"Incremental delta rebuild median ({medianMs}ms across {sampleIterations} samples: " +
            $"[{string.Join(", ", samples)}]) exceeds the 500ms NFR8 budget. " +
            "If this reflects a real regression, file an issue; if it reflects machine variance in CI, " +
            "the advisory mode (continue-on-error: true) keeps it non-blocking while the baseline is collected.");
    }

    [Fact]
    public void MalformedProjection_ToleratedWithoutGeneratorException() {
        // Contract for invalid / partial syntax tolerance (Task 2.3).
        //
        // The story spec lists three desired properties:
        //   (a) Zero generated files for the malformed type.
        //   (b) A Roslyn-level compile diagnostic (CS*) — not a generator one.
        //   (c) The generator pipeline must not throw.
        //
        // The real, observed tolerance contract of the current generator is a
        // subset: (b) and (c) hold strictly; (a) does NOT — the generator
        // emits output for any type decorated with [Projection] based on
        // whatever Roslyn's error-recovered semantic model produces. For a
        // class like `Bad { public string X { get }`, Roslyn still synthesizes
        // a type symbol with one (incomplete) property, and the emit stage
        // therefore produces its usual fan-out of artifacts.
        //
        // This divergence is acceptable for the inner-loop scenario because
        // (b) + (c) already give the developer the right feedback: the real
        // compile error is CS*, and `dotnet watch` will not crash while they
        // are mid-edit. Strictly enforcing (a) would require the emit stage
        // to gate on "all properties parsed cleanly", which is outside the
        // Story 1.8 scope.
        //
        // Tracked as a deferred hardening task:
        //   _bmad-output/implementation-artifacts/deferred-work.md —
        //   "Gate emit stage on clean parse of malformed [Projection] types".
        CancellationToken ct = TestContext.Current.CancellationToken;

        const string malformed = @"
using Hexalith.FrontComposer.Contracts.Attributes;

namespace TestDomain;

[BoundedContext(""Bad"")]
[Projection]
public partial class Bad { public string X { get }";

        CSharpCompilation compilation = CompilationHelper.CreateCompilation(malformed);
        FrontComposerGenerator generator = new();

        GeneratorDriver driver = CSharpGeneratorDriver.Create(generator);

        // (c) The generator must not throw — this is what the developer inner
        //     loop actually exercises whenever `dotnet watch` runs against a
        //     file the developer is mid-way through editing.
        GeneratorDriverRunResult result = Should
            .NotThrow(() => driver.RunGenerators(compilation, ct).GetRunResult());

        // (b) Compile diagnostics come from Roslyn (CS*), not from the generator —
        //     the developer sees the real problem (missing `;`, missing `}`) from
        //     the compiler, not a generator-specific error.
        compilation.GetDiagnostics(ct)
            .Any(d => d.Severity == DiagnosticSeverity.Error && d.Id.StartsWith("CS", System.StringComparison.Ordinal))
            .ShouldBeTrue("Malformed source must surface a Roslyn compile error (CS*) so the developer sees the real problem.");

        // (c') Zero generator-produced errors. The generator may warn (HFC1xxx)
        //      on domain modeling issues, but it must not raise error-severity
        //      diagnostics on half-written code.
        result.Diagnostics
            .Where(d => d.Severity == DiagnosticSeverity.Error)
            .ShouldBeEmpty("The generator must not raise error-severity diagnostics on malformed input — that would regress the inner-loop experience.");

        // (c'') The generator's emitted code must not introduce NEW error-severity
        //       diagnostics beyond what the malformed original already had. Re-compile
        //       with the generated syntax trees appended and count only error-severity
        //       CS* diagnostics not present in the pre-generation compilation. This
        //       guards against a regression where error-recovered semantic model output
        //       causes the emitter to generate code that itself fails to compile
        //       (making the developer's inner loop *worse* than the original error).
        var originalErrorLocations = compilation
            .GetDiagnostics(ct)
            .Where(d => d.Severity == DiagnosticSeverity.Error && d.Id.StartsWith("CS", System.StringComparison.Ordinal))
            .Select(d => d.Id + "@" + d.Location.GetLineSpan().Path + ":" + d.Location.GetLineSpan().StartLinePosition.Line)
            .ToImmutableHashSet();

        CSharpCompilation postGenCompilation = compilation.AddSyntaxTrees(result.GeneratedTrees);
        Diagnostic[] newGeneratorErrors = postGenCompilation
            .GetDiagnostics(ct)
            .Where(d => d.Severity == DiagnosticSeverity.Error && d.Id.StartsWith("CS", System.StringComparison.Ordinal))
            .Where(d => {
                string key = d.Id + "@" + d.Location.GetLineSpan().Path + ":" + d.Location.GetLineSpan().StartLinePosition.Line;
                return !originalErrorLocations.Contains(key);
            })
            .ToArray();

        newGeneratorErrors.ShouldBeEmpty(
            $"The generator emitted code that introduces {newGeneratorErrors.Length} NEW compile error(s) " +
            "beyond the malformed source's original diagnostics. This regresses the inner-loop experience: " +
            "the developer sees generator-amplified noise on top of the real edit-in-progress error. " +
            $"New errors: [{string.Join("; ", newGeneratorErrors.Select(d => d.Id + " " + d.GetMessage(System.Globalization.CultureInfo.InvariantCulture)))}].");
    }

    // Story 9-3 — IDE-MUST-006: NFR8 evidence row claims CI-blocking 500 ms warm-update
    // budget for the IdeParity fixture. This test exercises the deterministic
    // samples/IdeParityCounter sources and asserts both the cold first-run budget and the
    // incremental warm-update budget. A cold run is intentionally given more headroom
    // (Roslyn's first-time analyzer load is dominated by JIT and metadata parsing); the
    // warm-update budget is the contract IDE adopters care about because that is what they
    // experience on every edit.
    [Fact]
    [Trait("MatrixRowId", "IDE-MUST-006")]
    public void IdeParityCounterFixture_WarmUpdateAndColdRunStayWithinNfr8Budgets() {
        const long warmUpdateBudgetMs = 500;
        const long coldRunBudgetMs = 5000;

        CancellationToken ct = TestContext.Current.CancellationToken;

        string fixtureSource = Hexalith.FrontComposer.SourceTools.Tests.IdeParity
            .IdeParityConformanceUtilityTests.LoadIdeParityCounterFixtureSource();
        CSharpCompilation initialCompilation = CompilationHelper.CreateCompilation(fixtureSource);
        FrontComposerGenerator generator = new();
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            [generator.AsSourceGenerator()],
            driverOptions: new GeneratorDriverOptions(
                disabledOutputs: IncrementalGeneratorOutputKind.None,
                trackIncrementalGeneratorSteps: true));

        // Cold run: first invocation against a fresh driver. This populates analyzer/JIT
        // caches and is allowed a wider budget than the steady-state warm update.
        var coldStopwatch = Stopwatch.StartNew();
        driver = driver.RunGenerators(initialCompilation, ct);
        coldStopwatch.Stop();
        GeneratorDriverRunResult coldResult = driver.GetRunResult();
        coldResult.Diagnostics.Where(d => d.Severity == DiagnosticSeverity.Error).ShouldBeEmpty(
            "Cold run on the IdeParityCounter fixture must not emit error-severity diagnostics.");
        coldStopwatch.ElapsedMilliseconds.ShouldBeLessThan(
            coldRunBudgetMs,
            $"Cold run for samples/IdeParityCounter took {coldStopwatch.ElapsedMilliseconds} ms; budget is {coldRunBudgetMs} ms.");

        // Warm update: mutate the projection by adding one property and re-run. This is the
        // NFR8 budget that IDE-MUST-006 gates.
        string mutatedSource = fixtureSource.Replace(
            "public string Status { get; set; } = string.Empty;",
            "public string Status { get; set; } = string.Empty;\n    public int Version { get; set; }",
            StringComparison.Ordinal);
        CSharpCompilation mutatedCompilation = initialCompilation.ReplaceSyntaxTree(
            initialCompilation.SyntaxTrees.First(t => t.GetText().ToString().Contains("IdeParityCounterProjection")),
            CSharpSyntaxTree.ParseText(mutatedSource, cancellationToken: ct));

        // Warmup pass to absorb the JIT cost of the delta path itself; not measured.
        driver = driver.RunGenerators(mutatedCompilation, ct);
        // Re-seed once so the next RunGenerators(initial) is a real delta.
        driver = driver.RunGenerators(initialCompilation, ct);

        const int sampleIterations = 5;
        long[] samples = new long[sampleIterations];
        GeneratorDriverRunResult lastDeltaResult = null!;
        for (int i = 0; i < sampleIterations; i++) {
            var sw = Stopwatch.StartNew();
            driver = driver.RunGenerators(mutatedCompilation, ct);
            sw.Stop();
            samples[i] = sw.ElapsedMilliseconds;
            lastDeltaResult = driver.GetRunResult();
            // Re-seed to make the next iteration a real delta.
            driver = driver.RunGenerators(initialCompilation, ct);
        }

        long medianMs = samples.OrderBy(x => x).ElementAt(sampleIterations / 2);
        lastDeltaResult.Diagnostics.Where(d => d.Severity == DiagnosticSeverity.Error).ShouldBeEmpty(
            "Warm update on the IdeParityCounter fixture must not emit error-severity diagnostics.");
        medianMs.ShouldBeLessThan(
            warmUpdateBudgetMs,
            $"Warm update median for samples/IdeParityCounter ({medianMs} ms across {sampleIterations} samples: " +
            $"[{string.Join(", ", samples)}]) exceeds the {warmUpdateBudgetMs} ms NFR8 budget.");
    }
}

using Hexalith.FrontComposer.SourceTools.Tests.Parsing.TestFixtures;

using Microsoft.CodeAnalysis;
