    [Fact]
    public void CompatibilitySuppressionEvidence_IsDeterministicAndBounded() {
        FileInfo suppression = new(Path.Combine(ProjectRoot().FullName, "docs", "diagnostics", "compatibility-suppressions.json"));
        suppression.Exists.ShouldBeTrue("Story 9-4 compatibility evidence file is missing.");

        JsonObject json = JsonNode.Parse(File.ReadAllText(suppression.FullName, Encoding.UTF8))!.AsObject();
        ValidateCompatibilitySuppressionsJson(json).ShouldBeEmpty();
        json["schemaVersion"]!.GetValue<string>().ShouldBe(CompatibilitySuppressionsSchemaVersion);
        json["currentRelease"]!.GetValue<string>().ShouldBe("v6.0");
        JsonArray suppressions = json["suppressions"]!.AsArray();

        suppressions.Count.ShouldBe(32, "only the 28 SDK enum comparisons and four exact framework drops are approved for v6.0.");

        HashSet<string> apiCompatDiagnosticIds = ["CP0001", "CP0002", "CP0008", "PKV006"];
        Regex targetReleaseRegex = TargetReleaseRegex();
        HashSet<(string Package, string Tfm, string Diagnostic, string Old)> uniqueness = [];

        foreach (JsonNode? node in suppressions) {
            JsonObject item = node!.AsObject();
            string package = item["package"]!.GetValue<string>();
            string tfm = item["tfm"]!.GetValue<string>();
            string oldSig = item["oldSignature"]!.GetValue<string>();
            string newState = item["newState"]!.GetValue<string>();
            string apiCompatDiagnosticId = item["apiCompatDiagnosticId"]!.GetValue<string>();
            string target = item["targetRelease"]!.GetValue<string>();
            string rationale = item["reviewerRationale"]!.GetValue<string>();

            package.ShouldStartWith("Hexalith.FrontComposer.");
            tfm.ShouldNotBeNullOrWhiteSpace();
            oldSig.ShouldNotBeNullOrWhiteSpace();
            newState.ShouldNotBeNullOrWhiteSpace();
            apiCompatDiagnosticIds.ShouldContain(apiCompatDiagnosticId, $"ApiCompat diagnostic '{apiCompatDiagnosticId}' is not governed.");
            item.ContainsKey("hfcId").ShouldBeFalse("manual package moves must not claim an unrelated HFC migration diagnostic.");
            targetReleaseRegex.IsMatch(target).ShouldBeTrue($"targetRelease '{target}' malformed.");

            if (package == "Hexalith.FrontComposer.Contracts" && apiCompatDiagnosticId == "CP0001") {
                oldSig.ShouldStartWith("T:", customMessage: "Contracts CP0001 suppressions must identify an exact type.");
                TryParseMovedTypeState(newState, out string? newSignature, out string? newAssembly, out bool namespacePreserved)
                    .ShouldBeTrue($"{oldSig} must identify its exact destination type and assembly.");
                string oldSignature = oldSig[2..];
                if (namespacePreserved) {
                    newAssembly.ShouldBe("Hexalith.FrontComposer.Contracts.UI", $"{oldSig} may preserve its namespace only when moving to Contracts.UI.");
                    newSignature.ShouldBe(oldSignature, $"{oldSig} may say namespace preserved only for an exact same-FQN move.");
                }
                else {
                    newSignature.ShouldNotBe(oldSignature, $"{oldSig} must name its ownership-correct Story 11.12 namespace.");
                    newAssembly.ShouldBeOneOf("Hexalith.FrontComposer.Shell", "Hexalith.FrontComposer.Testing");
                }
            }

            if (package == "Hexalith.FrontComposer.Shell" && apiCompatDiagnosticId == "CP0001") {
                oldSig.ShouldStartWith("T:", customMessage: "Shell CP0001 suppressions must identify an exact removed type.");
                TryParseMovedTypeState(newState, out string? newSignature, out string? newAssembly, out bool namespacePreserved)
                    .ShouldBeTrue($"{oldSig} must identify its exact destination type and assembly.");
                newAssembly.ShouldBe("Hexalith.FrontComposer.Shell");
                namespacePreserved.ShouldBeFalse($"{oldSig} is a namespace relocation and cannot claim namespace preservation.");
                newSignature.ShouldNotBe(oldSig[2..], $"{oldSig} must name a different destination namespace.");
                target.ShouldBe("v3.0", "public hydration-type consolidation and worker relocations are next-major changes.");
                Version.Parse(item["expiresAfter"]!.GetValue<string>()[1..])
                    .ShouldBeGreaterThan(Version.Parse(target[1..]), "CP0001 evidence must expire after its target release.");
            }

            string trimmed = rationale.Trim();
            trimmed.Length.ShouldBeInRange(16, 400, $"rationale must be 16-400 visible chars (got {trimmed.Length}).");
            if (trimmed.Any(char.IsControl)) {
                Assert.Fail("rationale must not contain control characters.");
            }

            uniqueness.Add((package, tfm, apiCompatDiagnosticId, oldSig)).ShouldBeTrue($"duplicate suppression row for ({package}, {tfm}, {apiCompatDiagnosticId}, {oldSig}).");
        }

        string[] trackedRows = [.. suppressions
            .Select(node => node!.AsObject())
            .Select(item => {
                string key = $"{item["package"]!.GetValue<string>()}|{item["tfm"]!.GetValue<string>()}|{item["apiCompatDiagnosticId"]!.GetValue<string>()}|{item["oldSignature"]!.GetValue<string>()}";
                return item["comparisonTfm"] is JsonValue comparison ? $"{key}|{comparison.GetValue<string>()}" : key;
            })
            .OrderBy(value => value, Ordinal)];

        var exactApiCompatRows = new List<string>();
        foreach (string suppressionPath in Directory.EnumerateFiles(
            Path.Combine(ProjectRoot().FullName, "src"),
            "CompatibilitySuppressions.xml",
            SearchOption.AllDirectories)) {
            string package = new FileInfo(suppressionPath).Directory!.Name;
            XDocument apiCompat = XDocument.Load(suppressionPath);
            foreach (XElement item in apiCompat.Root!.Elements("Suppression")) {
                string diagnosticId = item.Element("DiagnosticId")!.Value;
                string target = item.Element("Target")!.Value;
                if (diagnosticId == "PKV006") {
                    package.ShouldBeOneOf("Hexalith.FrontComposer.Contracts.UI", "Hexalith.FrontComposer.Mcp", "Hexalith.FrontComposer.Shell", "Hexalith.FrontComposer.Testing");
                    target.ShouldBe("net10.0");
                    item.Elements().Select(element => element.Name.LocalName).ShouldBe(["DiagnosticId", "Target"]);
                    exactApiCompatRows.Add($"{package}|net10.0|{diagnosticId}|{target}");
                    continue;
                }
                if (package == "Hexalith.FrontComposer.Contracts") {
                    diagnosticId.ShouldBe("CP0008", "only SDK-recorded inherited Enum interface comparisons are approved.");
                    target.ShouldStartWith("T:");
                    Type enumType = typeof(FcDiagnosticIds).Assembly.GetType(target[2..], throwOnError: true)!;
                    enumType.IsEnum.ShouldBeTrue();
                    typeof(ISpanFormattable).IsAssignableFrom(enumType).ShouldBeTrue("the net11.0 runtime face must retain the inherited interface.");
                }
                else if (package == "Hexalith.FrontComposer.Shell") {
                    ShellApiCompatibilityDiagnosticIds.ShouldContain(
                        diagnosticId,
                        "Shell suppressions are exact type relocations, member assembly-binding changes, or interface changes.");
                }
                else if (package == "Hexalith.FrontComposer.Mcp") {
                    diagnosticId.ShouldBe("CP0001", "MCP suppressions are exact benchmark type removals.");
                    ExpectedMcpBenchmarkRemovalTargets.ShouldContain(item.Element("Target")!.Value);
                }
                else {
                    Assert.Fail($"{package} has an unreviewed package-validation suppression file.");
                }

                item.Element("IsBaselineSuppression")!.Value.ShouldBe("true");
                string left = item.Element("Left")!.Value;
                string right = item.Element("Right")!.Value;
                string tfm = left.Split('/')[1];
                string key = $"{package}|{tfm}|{diagnosticId}|{target}";
                if (package == "Hexalith.FrontComposer.Contracts" && diagnosticId == "CP0008") {
                    left.ShouldBe($"lib/net10.0/{package}.dll");
                    right.ShouldBe($"lib/netstandard2.0/{package}.dll");
                    key += "|netstandard2.0";
                }
                else {
                    right.ShouldBe(left, "a suppression must not widen package-validation comparison scope.");
                }
                exactApiCompatRows.Add(key);
            }
        }

        exactApiCompatRows.Sort(Ordinal);

        exactApiCompatRows.ShouldBe(trackedRows, ignoreOrder: false,
            customMessage: "Every ApiCompat suppression must have one exact package/TFM/type evidence row, with no untracked or stale entries.");
    }

