    [Fact()]
    public void InvalidOption_FallsBackToDocumentedSafeDefault_NotSilentDisable() {
        // Story §"Validate analyzer-configured size/count/severity options before comparison;
        // invalid option values emit deterministic configuration diagnostics and fall back only
        // to documented safe defaults." Asserts: drift comparison still runs (visible drift
        // diagnostic is still emitted) when an unrelated option is invalid — the generator must
        // not silently disable drift detection on a single bad option.
        // Story 9-1 review CB-33: positively assert (a) HFC1067 fires for the bad option, AND
        // (b) drift comparison still surfaces the structural drift — proving the documented
        // default applied rather than a silent disable.
        const string source = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            namespace TestDomain;
            [BoundedContext("Orders")]
            [Projection]
            public partial class OrderProjection {
                public string Id { get; set; } = string.Empty;
                public string NewProp { get; set; } = string.Empty;
            }
            """;
        const string baseline = """
            { "schemaVersion": "frontcomposer.generated-ui-baseline.v1",
              "algorithm": "frontcomposer-structural-v1",
              "contracts": [{ "family": "projection", "type": "TestDomain.OrderProjection", "boundedContext": "Orders",
                "properties": [{ "name": "Id", "category": "String", "nullable": false }] }] }
            """;

        IReadOnlyList<Diagnostic> diagnostics = RunWithOptionAndBaseline(
            source, baseline, "build_property.HfcDriftMaxDiagnostics", "-1");

        diagnostics.Any(d => d.Id == ConfigDiagnosticId
                          && d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("HfcDriftMaxDiagnostics", StringComparison.OrdinalIgnoreCase))
            .ShouldBeTrue("CB-33 — HFC1067 must fire for the invalid option.");
        diagnostics.Any(d => d.Id == "HFC1065" && d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("NewProp", StringComparison.Ordinal))
            .ShouldBeTrue("AC9 + CB-33 — drift detection must keep working under documented safe defaults; invalid options must not silently disable it.");
    }

    [Fact()]
    public void OptionParsing_IsCultureInvariant() {
        // AC19 — parsing "1,000" must NOT be accepted as 1000 under fr-FR. The binder must use
        // CultureInfo.InvariantCulture; the value should be rejected with the same configuration
        // diagnostic regardless of host culture.
        CultureInfo prior = System.Globalization.CultureInfo.CurrentCulture;
        try {
            System.Globalization.CultureInfo.CurrentCulture = new System.Globalization.CultureInfo("fr-FR");

            IReadOnlyList<Diagnostic> diagnostics = RunWithOption(SourceWithProjection, "build_property.HfcDriftMaxDiagnostics", "1,000");
            diagnostics.Any(d => d.Id == ConfigDiagnosticId).ShouldBeTrue(
                "AC19 — option parsing must be culture-invariant; 1,000 is not a valid integer.");
        }
        finally {
            System.Globalization.CultureInfo.CurrentCulture = prior;
        }
    }

    private static System.Collections.Immutable.ImmutableArray<Diagnostic> RunWithOption(string source, string optionKey, string optionValue) {
        // Story 9-1 review CB-35: keep modeling the production opt-in path explicitly. The
        // configuration-diagnostic check fires before the Enabled gate today, but routing
        // through DriftEnabledOptions guards against a future refactor that moves option
        // validation behind the gate.
        CancellationToken ct = TestContext.Current.CancellationToken;
        CSharpCompilation compilation = CompilationHelper.CreateCompilation(source);
        FrontComposerGenerator generator = new();
        Dictionary<string, string> extra = new(StringComparer.OrdinalIgnoreCase) { [optionKey] = optionValue };
        AnalyzerConfigOptionsProvider options = CompilationHelper.DriftEnabledOptions(extra);

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            generators: [generator.AsSourceGenerator()],
            additionalTexts: [],
            optionsProvider: options);
        driver = driver.RunGenerators(compilation, ct);
        return driver.GetRunResult().Diagnostics;
    }

    private static System.Collections.Immutable.ImmutableArray<Diagnostic> RunWithOptionAndBaseline(string source, string baselineJson, string optionKey, string optionValue) {
        CancellationToken ct = TestContext.Current.CancellationToken;
        CSharpCompilation compilation = CompilationHelper.CreateCompilation(source);
        FrontComposerGenerator generator = new();
        AdditionalText baselineText = new InMemoryAdditionalText("frontcomposer.drift-baseline.json", baselineJson);
        Dictionary<string, string> extra = new(StringComparer.OrdinalIgnoreCase) { [optionKey] = optionValue };
        AnalyzerConfigOptionsProvider options = CompilationHelper.DriftEnabledOptions(extra);

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            generators: [generator.AsSourceGenerator()],
            additionalTexts: [baselineText],
            optionsProvider: options);
        driver = driver.RunGenerators(compilation, ct);
        return driver.GetRunResult().Diagnostics;
    }

    private static System.Collections.Immutable.ImmutableArray<Diagnostic> RunWithEnabledOverrideAndBaseline(
        string source,
        string baselineJson,
        string enabledRaw,
        string optionKey = "build_property.HfcDriftDetectionEnabled") {
        CancellationToken ct = TestContext.Current.CancellationToken;
        CSharpCompilation compilation = CompilationHelper.CreateCompilation(source);
        FrontComposerGenerator generator = new();
        AdditionalText baselineText = new InMemoryAdditionalText("frontcomposer.drift-baseline.json", baselineJson);
        // Bypass DriftEnabledOptions's auto-set so we can probe the exact raw value.
        AnalyzerConfigOptionsProvider options = new InMemoryRawOptionsProvider(
            new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase) {
                [optionKey] = enabledRaw,
            });

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            generators: [generator.AsSourceGenerator()],
            additionalTexts: [baselineText],
            optionsProvider: options);
        driver = driver.RunGenerators(compilation, ct);
        return driver.GetRunResult().Diagnostics;
    }

    private sealed class InMemoryRawOptionsProvider(IReadOnlyDictionary<string, string> values) : AnalyzerConfigOptionsProvider {
        public override AnalyzerConfigOptions GlobalOptions { get; } = new InMemoryRawOptions(values);
        public override AnalyzerConfigOptions GetOptions(SyntaxTree tree) => GlobalOptions;
        public override AnalyzerConfigOptions GetOptions(AdditionalText textFile) => GlobalOptions;

        private sealed class InMemoryRawOptions(IReadOnlyDictionary<string, string> values) : AnalyzerConfigOptions {
            public override bool TryGetValue(string key, out string value) {
                if (values.TryGetValue(key, out string? v)) {
                    value = v;
                    return true;
                }
                value = null!;
                return false;
            }
        }
    }
}

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;

using Shouldly;

namespace Hexalith.FrontComposer.SourceTools.Tests.Drift.Baseline;

/// <summary>
/// AC8 / T1 + T2 — missing baseline path. Two distinct diagnostics:
/// (a) baseline is absent / first run, (b) configured baseline path is invalid (analyzer config
/// points at a non-existent file). Each emits one actionable diagnostic and suppresses drift
/// comparison for the affected baseline. Both must reference the Story 9-2 CLI handoff text.
/// </summary>
public sealed class DriftBaselineMissingDiagnosticTests {
    private const string SkipReason = "RED-PHASE: T1 + T2 — baseline-missing diagnostic not yet introduced.";

    [Fact()]
    public void NoBaselineProvided_AndDriftDetectionOptedIn_EmitsFirstRunDiagnostic_Once() {
        const string source = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            namespace TestDomain;
            [BoundedContext("Orders")]
            [Projection]
            public partial class OrderProjection {
                public string Id { get; set; } = string.Empty;
            }
            """;

        IReadOnlyList<Diagnostic> diagnostics = RunWithoutBaseline(source);

        Diagnostic[] missing = [.. diagnostics.Where(d => d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("baseline", StringComparison.OrdinalIgnoreCase)
                                                       && (d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("first run", StringComparison.OrdinalIgnoreCase)
                                                        || d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("missing", StringComparison.OrdinalIgnoreCase)))];
        missing.Length.ShouldBe(1, "AC8 — exactly one first-run/missing-baseline diagnostic, regardless of declaration count.");
        missing[0].Severity.ShouldBe(DiagnosticSeverity.Warning);
        missing[0].GetMessage(System.Globalization.CultureInfo.InvariantCulture).ShouldContain("Story 9-2", Case.Insensitive);
    }

    [Fact()]
    public void ConfiguredPathDoesNotResolve_EmitsInvalidPathDiagnostic_DistinctFromFirstRun() {
        // Activation contract: when build_property.HfcDriftBaselinePath points at a path that
        // does not match any AdditionalText, the analyzer reports it as a *configuration* failure,
        // not a first-run diagnostic. The two MUST carry different IDs.
        // Story 9-1 review CB-32: positively assert distinct HFC IDs (HFC1058 vs HFC1059) —
        // wording-only differentiation is brittle.
        const string source = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            namespace TestDomain;
            [BoundedContext("Orders")]
            [Projection]
            public partial class OrderProjection {
                public string Id { get; set; } = string.Empty;
            }
            """;

        IReadOnlyList<Diagnostic> withoutBaseline = RunWithoutBaseline(source);
        IReadOnlyList<Diagnostic> invalidPath = RunWithMisconfiguredBaselinePath(source);

        Diagnostic? missing = withoutBaseline.FirstOrDefault(d => d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("baseline", StringComparison.OrdinalIgnoreCase)
                                                               && (d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("first run", StringComparison.OrdinalIgnoreCase)
                                                                || d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("missing", StringComparison.OrdinalIgnoreCase)));
        Diagnostic? invalid = invalidPath.FirstOrDefault(d => d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("baseline", StringComparison.OrdinalIgnoreCase)
                                                           && d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("path", StringComparison.OrdinalIgnoreCase));

        _ = missing.ShouldNotBeNull();
        _ = invalid.ShouldNotBeNull();
        missing!.Id.ShouldNotBe(invalid!.Id, "AC8 — missing-baseline (HFC1058) and invalid-path (HFC1059) MUST carry distinct IDs.");
        missing.Id.ShouldBe("HFC1058", "AC8 — first-run/missing baseline pinned to HFC1058.");
        invalid.Id.ShouldBe("HFC1059", "AC8 — invalid-configured-path pinned to HFC1059.");

        invalidPath.Any(d => d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("first run", StringComparison.OrdinalIgnoreCase)).ShouldBeFalse(
            "AC8 — the invalid-path diagnostic must NOT reuse the first-run wording.");
    }

    [Fact()]
    public void MissingBaseline_SuppressesAllDriftComparisonDiagnostics_ForThatBaseline() {
        // Even though the source declares two projections, the missing-baseline diagnostic must
        // suppress structural-drift / metadata-drift comparison; only the missing-baseline
        // signal should be visible (plus unrelated existing generator diagnostics).
        const string source = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            namespace TestDomain;
            [BoundedContext("Orders")]
            [Projection]
            public partial class A { public string Id { get; set; } = string.Empty; }
            [BoundedContext("Orders")]
            [Projection]
            public partial class B { public string Id { get; set; } = string.Empty; }
            """;

        IReadOnlyList<Diagnostic> diagnostics = RunWithoutBaseline(source);

        diagnostics.Any(d => d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("structural drift", StringComparison.OrdinalIgnoreCase)
                          || d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("metadata drift", StringComparison.OrdinalIgnoreCase))
            .ShouldBeFalse("AC8 — missing baseline suppresses drift comparison.");
    }

    private static System.Collections.Immutable.ImmutableArray<Diagnostic> RunWithoutBaseline(string source) {
        CancellationToken ct = TestContext.Current.CancellationToken;
        CSharpCompilation compilation = CompilationHelper.CreateCompilation(source);
        FrontComposerGenerator generator = new();
        // Drift-detection opt-in is expected to be modelled either via a project-level analyzer
        // config (build_property.HfcDriftDetectionEnabled) or via the presence of a baseline
        // AdditionalText. The activation harness will swap this for the real option.
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            generators: [generator.AsSourceGenerator()],
            optionsProvider: EnabledOptions());
        driver = driver.RunGenerators(compilation, ct);
        return driver.GetRunResult().Diagnostics;
    }

    private static System.Collections.Immutable.ImmutableArray<Diagnostic> RunWithMisconfiguredBaselinePath(string source) {
        CancellationToken ct = TestContext.Current.CancellationToken;
        CSharpCompilation compilation = CompilationHelper.CreateCompilation(source);
        FrontComposerGenerator generator = new();
        AnalyzerConfigOptionsProvider options = EnabledOptions(new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase) {
            ["build_property.HfcDriftBaselinePath"] = "does/not/exist.json",
        });
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            generators: [generator.AsSourceGenerator()],
            optionsProvider: options);
        driver = driver.RunGenerators(compilation, ct);
        return driver.GetRunResult().Diagnostics;
    }

    private static InMemoryOptions EnabledOptions(Dictionary<string, string>? extra = null) {
        Dictionary<string, string> values = extra is null
            ? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            : new Dictionary<string, string>(extra, StringComparer.OrdinalIgnoreCase);
        values["build_property.HfcDriftDetectionEnabled"] = "true";
        return new InMemoryOptions(values);
    }

    private sealed class InMemoryOptions(IReadOnlyDictionary<string, string> values) : AnalyzerConfigOptionsProvider {
        public override AnalyzerConfigOptions GlobalOptions { get; } = new InMemory(values);
        public override AnalyzerConfigOptions GetOptions(SyntaxTree tree) => GlobalOptions;
        public override AnalyzerConfigOptions GetOptions(AdditionalText textFile) => GlobalOptions;

        private sealed class InMemory(IReadOnlyDictionary<string, string> values) : AnalyzerConfigOptions {
            public override bool TryGetValue(string key, out string value) {
                if (values.TryGetValue(key, out string? v)) {
                    value = v;
                    return true;
                }

                value = string.Empty;
                return false;
            }
        }
    }
}

using System.Reflection;

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;

using Shouldly;

using static Hexalith.FrontComposer.SourceTools.Tests.Drift.Comparison.DriftClassifierProjectionPropertyTests;

namespace Hexalith.FrontComposer.SourceTools.Tests.Drift.Baseline;

/// <summary>
/// AC9 / T1 + T2 + T4 — trust failure matrix. Every fail-closed scenario emits a deterministic
/// Error diagnostic and suppresses drift comparison for the affected baseline. There is no
/// "last writer wins" merge across baseline files — duplicate identity across files is itself
/// a trust failure.
/// </summary>
public sealed class DriftBaselineTrustFailureTests {
    private const string SkipReason = "RED-PHASE: T1 + T2 — baseline trust-failure pipeline not yet introduced.";

    public static TheoryData<string, string> TrustFailureFixtures() => new() {
        { "baseline-empty.json",                     "empty" },
        { "baseline-malformed.json",                 "malformed" },
        { "baseline-unsupported-schema.json",        "schema version" },
        { "baseline-unsupported-algorithm.json",     "algorithm" },
        { "baseline-oversized.json",                 "oversized" },
        { "baseline-duplicate-identity-within.json", "duplicate identity" },
        { "baseline-invariant-violation.json",       "invariant" },
    };

    [Theory()]
    [MemberData(nameof(TrustFailureFixtures))]
    public void Fixture_FailsClosed_WithErrorAndSuppressedComparison(string fixtureFileName, string expectedMessageToken) {
        const string source = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            namespace TestDomain;
            [BoundedContext("Orders")]
            [Projection]
            public partial class OrderProjection { public string Id { get; set; } = string.Empty; }
            """;
        string fixtureContent = LoadFixture(fixtureFileName);

        // Story 9-1 review P2 + P10: the oversized fixture is a stable 520-byte artifact and
        // does not exceed the default 256 KB cap on its own. Tighten MaxBaselineBytes to a
        // small value so the cap fires deterministically without checking in a multi-MB
        // fixture (the previous implementation cheated by looking for a `_oversizedHint`
        // sentinel substring in production code, which leaked test fixtures into the loader).
        int? maxBytesOverride = string.Equals(fixtureFileName, "baseline-oversized.json", StringComparison.Ordinal)
            ? 100
            : null;

        IReadOnlyList<Diagnostic> diagnostics = Run(source, fixtureContent, maxBytesOverride);

        Diagnostic? trustFailure = diagnostics.FirstOrDefault(d =>
            d.Severity == DiagnosticSeverity.Error
            && d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains(expectedMessageToken, StringComparison.OrdinalIgnoreCase));
        _ = trustFailure.ShouldNotBeNull(
            $"AC9 — fixture {fixtureFileName} must emit a deterministic Error diagnostic carrying the token '{expectedMessageToken}'.");

        diagnostics.Any(d => d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("structural drift", StringComparison.OrdinalIgnoreCase))
            .ShouldBeFalse($"AC9 — trust failure must suppress structural-drift comparison for {fixtureFileName}.");
    }

    [Fact()]
    public void OversizedCap_AtExactByteCap_DoesNotFire() {
        // Story 9-1 review CB-11 boundary: the loader uses `>` strictly when comparing byte
        // length to MaxBaselineBytes; a baseline at exactly the configured cap is allowed.
        // Build a minimal-valid baseline, measure its byte length, and pass that exact value
        // as the cap. The loader must NOT emit HFC1063 (BaselineBoundsExceeded) at the boundary.
        const string source = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            namespace TestDomain;
            [BoundedContext("Orders")]
            [Projection]
            public partial class OrderProjection { public string Id { get; set; } = string.Empty; }
            """;
        const string baseline = """
            { "schemaVersion": "frontcomposer.generated-ui-baseline.v1",
              "algorithm": "frontcomposer-structural-v1",
              "contracts": [{ "family": "projection", "type": "TestDomain.OrderProjection", "boundedContext": "Orders",
                "properties": [{ "name": "Id", "category": "String", "nullable": false }] }] }
            """;
        int exactBytes = System.Text.Encoding.UTF8.GetByteCount(baseline);

        IReadOnlyList<Diagnostic> diagnostics = Run(source, baseline, maxBaselineBytesOverride: exactBytes);

        diagnostics.Any(d => d.Id == "HFC1063")
            .ShouldBeFalse("CB-11 — oversize cap is `>` strict; baseline at exactly MaxBaselineBytes must pass.");
    }

    [Fact()]
    public void OversizedCap_AtCapPlusOne_FailsClosed() {
        // Companion to the at-cap test: cap-1 fires HFC1063, proving the boundary is between
        // exactCap (allowed) and exactCap-1 (rejected).
        const string source = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            namespace TestDomain;
            [BoundedContext("Orders")]
            [Projection]
            public partial class OrderProjection { public string Id { get; set; } = string.Empty; }
            """;
        const string baseline = """
            { "schemaVersion": "frontcomposer.generated-ui-baseline.v1",
              "algorithm": "frontcomposer-structural-v1",
              "contracts": [{ "family": "projection", "type": "TestDomain.OrderProjection", "boundedContext": "Orders",
                "properties": [{ "name": "Id", "category": "String", "nullable": false }] }] }
            """;
        int exactBytes = System.Text.Encoding.UTF8.GetByteCount(baseline);

        IReadOnlyList<Diagnostic> diagnostics = Run(source, baseline, maxBaselineBytesOverride: exactBytes - 1);

        diagnostics.Any(d => d.Id == "HFC1063" && d.Severity == DiagnosticSeverity.Error)
            .ShouldBeTrue("CB-11 — baseline strictly larger than MaxBaselineBytes must emit HFC1063 Error.");
    }

    [Fact()]
    public void OversizedCap_MeasuresBytesNotChars_ForMultiByteUtf8() {
        // Story 9-1 review P10: oversize check uses `Encoding.UTF8.GetByteCount` (not character
        // count). Build a baseline where multi-byte (CJK) characters drive byte length above
        // a configured cap that the char count would not exceed.
        const string source = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            namespace TestDomain;
            [BoundedContext("Orders")]
            [Projection]
            public partial class OrderProjection { public string Id { get; set; } = string.Empty; }
            """;
        // Each CJK character is 3 bytes in UTF-8 but 1 char. Build a description ~50 chars but
        // ~150+ bytes; the cap below (set just under the byte length) must reject by bytes.
        string padding = new('漢', 60);
        string baseline = $$"""
            { "schemaVersion": "frontcomposer.generated-ui-baseline.v1",
              "algorithm": "frontcomposer-structural-v1",
              "contracts": [{ "family": "projection", "type": "TestDomain.OrderProjection", "boundedContext": "Orders",
                "displayName": "{{padding}}",
                "properties": [{ "name": "Id", "category": "String", "nullable": false }] }] }
            """;
        int byteCount = System.Text.Encoding.UTF8.GetByteCount(baseline);
        int charCount = baseline.Length;
        // Sanity guard: this fixture is only meaningful if byteCount > charCount + slack.
        byteCount.ShouldBeGreaterThan(charCount + 100, "CB-11 fixture must contain enough multi-byte chars to differentiate.");

        // Cap at a value below byteCount but above charCount. A char-counting impl would let
        // this through; the byte-counting impl must reject.
        int cap = (charCount + byteCount) / 2;
        IReadOnlyList<Diagnostic> diagnostics = Run(source, baseline, maxBaselineBytesOverride: cap);

        diagnostics.Any(d => d.Id == "HFC1063" && d.Severity == DiagnosticSeverity.Error)
            .ShouldBeTrue("P10 — oversize comparison must use UTF-8 byte count, not char count.");
    }

    [Fact()]
    public void Utf8Bom_OnValidBaseline_ParsesAsValid_NoTrustFailure() {
        // Story 9-1 review P11: `JsonDocument.Parse` rejects UTF-8 BOM, so the loader strips it
        // before parsing. Prefix a valid baseline with U+FEFF and assert no HFC1060 fires.
        const string source = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            namespace TestDomain;
            [BoundedContext("Orders")]
            [Projection]
            public partial class OrderProjection { public string Id { get; set; } = string.Empty; }
