        IReadOnlyList<Diagnostic> diagnostics = Run(source, baseline);

        diagnostics.Any(d => d.Id == "HFC1065"
                          && d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("Quantity", StringComparison.Ordinal)
                          && d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("added", StringComparison.OrdinalIgnoreCase)
                          && d.Severity == DiagnosticSeverity.Warning)
            .ShouldBeTrue("AC3 — command field add must emit one structural-drift Warning.");
    }

    [Fact()]
    public void CommandPropertyRemoved_EmitsStructuralDrift_WithFormInputHint() {
        // Story 9-1 review CB-8 (AC3 + T7 matrix): command field remove counterpart.
        const string baseline = """
            { "schemaVersion": "frontcomposer.generated-ui-baseline.v1",
              "algorithm": "frontcomposer-structural-v1",
              "contracts": [{ "family": "command", "type": "TestDomain.ConfirmCommand", "boundedContext": "Orders",
                "properties": [
                  { "name": "MessageId",  "category": "String", "nullable": false, "derivable": false },
                  { "name": "OldField",   "category": "String", "nullable": false, "derivable": false }
                ] }] }
            """;
        const string source = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            namespace TestDomain;
            [BoundedContext("Orders")]
            [Command]
            public partial class ConfirmCommand {
                public string MessageId { get; set; } = string.Empty;
            }
            """;

        IReadOnlyList<Diagnostic> diagnostics = Run(source, baseline);

        diagnostics.Any(d => d.Id == "HFC1065"
                          && d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("OldField", StringComparison.Ordinal)
                          && (d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("not found", StringComparison.OrdinalIgnoreCase)
                           || d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("removed", StringComparison.OrdinalIgnoreCase))
                          && d.Severity == DiagnosticSeverity.Warning)
            .ShouldBeTrue("AC3 — command field remove must emit one structural-drift Warning naming the removed property.");
    }

    private static string CategoryFor(string clrType) => clrType switch {
        "string" => "String",
        "int" => "Int32",
        "decimal" => "Decimal",
        "double" => "Double",
        "System.DateTime" => "DateTime",
        "System.DateTimeOffset" => "DateTimeOffset",
        _ => "Unknown",
    };

    private static System.Collections.Immutable.ImmutableArray<Diagnostic> Run(string source, string baselineJson) {
        CancellationToken ct = TestContext.Current.CancellationToken;
        CSharpCompilation compilation = CompilationHelper.CreateCompilation(source);
        FrontComposerGenerator generator = new();
        AdditionalText baselineText = new InMemoryAdditionalText("frontcomposer.drift-baseline.json", baselineJson);
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            generators: [generator.AsSourceGenerator()],
            additionalTexts: [baselineText],
            optionsProvider: CompilationHelper.DriftEnabledOptions());
        driver = driver.RunGenerators(compilation, ct);
        return driver.GetRunResult().Diagnostics;
    }
}

using System.Collections.Immutable;
using System.Reflection;

using Hexalith.FrontComposer.SourceTools.Drift;
using Hexalith.FrontComposer.SourceTools.Parsing;

using Shouldly;

namespace Hexalith.FrontComposer.SourceTools.Tests.Drift.Comparison;

/// <summary>
/// AC1 / T1 + T3 — the structural drift comparison seam. Asserts the planned internal
/// pure service surface (<c>DriftComparisonService.Compare(snapshot, baseline)</c>)
/// exists, returns a deterministic <c>DriftComparisonResult</c>, and treats partial-type
/// declaration order and baseline file order as semantically irrelevant. Memory rule
/// "comparison logic stays internal — no public CLI/code-fix/source-rewrite surface in 9-1"
/// is enforced by <see cref="Seam.DriftSeamPublicSurfaceContractTests"/>.
/// </summary>
public sealed class DriftComparisonServiceTests {
    private const string SkipReason = "RED-PHASE: T1 + T3 — DriftComparisonService not yet introduced.";

    [Fact()]
    public void Service_TypeIsInternal_AndExposesCompareMethodOnDomainAndBaseline() {
        Type? service = TryFindServiceType();

        _ = service.ShouldNotBeNull("AC1 / T3: planned `DriftComparisonService` must exist as an internal pure service.");
        service!.IsPublic.ShouldBeFalse("AC17 forbids public comparison API in 9-1.");

        // Story 9-1 review CB-1: pin the lookup to the canonical 2-arg overload by exact
        // parameter types. The earlier `OrderBy(parameters.Length).FirstOrDefault()` was
        // brittle: it would silently bind to a different (or null) method if a future overload
        // shifted positions, instead of asserting the contract. Production exposes:
        //   internal static DriftComparisonResult Compare(DriftCurrentSnapshot, DriftBaselineSet)
        // and a 4-arg variant with options; here we pin to the 2-arg one explicitly.
        MethodInfo? compare = service.GetMethod(
            "Compare",
            BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance,
            binder: null,
            types: [typeof(DriftCurrentSnapshot), typeof(DriftBaselineSet)],
            modifiers: null);
        _ = compare.ShouldNotBeNull("Service must expose Compare(DriftCurrentSnapshot, DriftBaselineSet).");
        ParameterInfo[] parameters = compare!.GetParameters();
        parameters[0].ParameterType.ShouldBe(typeof(DriftCurrentSnapshot));
        parameters[1].ParameterType.ShouldBe(typeof(DriftBaselineSet));
    }

    [Fact()]
    public void Result_IsDeterministicForIdenticalInputs() {
        // Same domain + same baseline ⇒ comparison results compare equal (value-based, ordered).
        var probe = InvocationProbe.CreateOrSkip();
        DriftComparisonResult first = probe.Compare(probe.SampleDomain, probe.SampleBaseline);
        DriftComparisonResult second = probe.Compare(probe.SampleDomain, probe.SampleBaseline);

        // Story 9-1 review CB-38: compare facts structurally (Id + Severity + Message) rather
        // than via `f.ToString()` — DriftDiagnosticFact does not override ToString, so the prior
        // assertion compared `Type.FullName` for every element and passed trivially.
        first.Diagnostics.Length.ShouldBe(second.Diagnostics.Length);
        for (int i = 0; i < first.Diagnostics.Length; i++) {
            DriftDiagnosticFact a = first.Diagnostics[i];
            DriftDiagnosticFact b = second.Diagnostics[i];
            a.Id.ShouldBe(b.Id, $"AC18 determinism — fact[{i}].Id differs.");
            a.Severity.ShouldBe(b.Severity, $"AC18 determinism — fact[{i}].Severity differs.");
            a.Message.ShouldBe(b.Message, $"AC18 determinism — fact[{i}].Message differs.");
        }
    }

    [Fact()]
    public void Result_IsIndependentOfPartialDeclarationOrder() {
        // T3: partial declarations of the same projection/command type may live in any file
        // order; merging must produce identical drift facts regardless of contract enumeration
        // order in the snapshot.
        // Story 9-1 review CB-2: actually permute. The earlier helpers returned the same
        // instance regardless of `reverse:`, so the test was a tautology.
        var probe = InvocationProbe.CreateOrSkip(twoContracts: true);
        DriftComparisonResult forward = probe.Compare(probe.SampleDomain, probe.SampleBaseline);
        DriftComparisonResult reverse = probe.Compare(probe.ReversedDomain, probe.SampleBaseline);

        AssertSameFacts(forward, reverse, "AC18 partial-declaration order must not affect drift output.");
    }

    [Fact()]
    public void Result_IsIndependentOfBaselineFileOrder() {
        // T2: when multiple AdditionalText baseline files are provided, ordinal-sorted path
        // normalization must produce identical drift facts regardless of enumeration order.
        // Story 9-1 review CB-2: actually permute the baseline contract array.
        var probe = InvocationProbe.CreateOrSkip(twoContracts: true);
        DriftComparisonResult forward = probe.Compare(probe.SampleDomain, probe.SampleBaseline);
        DriftComparisonResult reverse = probe.Compare(probe.SampleDomain, probe.ReversedBaseline);

        AssertSameFacts(forward, reverse, "AC18 baseline file enumeration order must not change drift output.");
    }

    private static void AssertSameFacts(DriftComparisonResult a, DriftComparisonResult b, string reason) {
        // Sort by Id+Message so we compare set equality. The comparison service guarantees
        // ordering, but the goal here is to assert that order independence holds at the *fact*
        // level — the production sort is exercised by DriftDiagnosticOrderingAndTruncationTests.
        IOrderedEnumerable<string> aKeys = a.Diagnostics.Select(f => f.Id + "|" + f.Message).OrderBy(s => s, StringComparer.Ordinal);
        IOrderedEnumerable<string> bKeys = b.Diagnostics.Select(f => f.Id + "|" + f.Message).OrderBy(s => s, StringComparer.Ordinal);
        aKeys.ShouldBe(bKeys, reason);
    }

    private static Type? TryFindServiceType() {
        Assembly sourceTools = typeof(DomainModel).Assembly;
        return sourceTools.GetTypes().FirstOrDefault(t =>
            t.Name == "DriftComparisonService"
            || t.Name.EndsWith("DriftComparisonService", StringComparison.Ordinal));
    }

    internal sealed class InvocationProbe {
        public required MethodInfo CompareMethod { get; init; }
        public required DriftCurrentSnapshot SampleDomain { get; init; }
        public required DriftBaselineSet SampleBaseline { get; init; }
        public required DriftCurrentSnapshot ReversedDomain { get; init; }
        public required DriftBaselineSet ReversedBaseline { get; init; }

        public DriftComparisonResult Compare(DriftCurrentSnapshot domain, DriftBaselineSet baseline)
            => (DriftComparisonResult)CompareMethod.Invoke(null, [domain, baseline])!;

        internal static InvocationProbe CreateOrSkip(bool twoContracts = false) {
            Type? type = TryFindServiceType()
                ?? throw new InvalidOperationException("DriftComparisonService not yet implemented.");
            // Story 9-1 review CB-1: pin to the exact 2-arg signature.
            MethodInfo compare = type.GetMethod(
                "Compare",
                BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance,
                binder: null,
                types: [typeof(DriftCurrentSnapshot), typeof(DriftBaselineSet)],
                modifiers: null)
                ?? throw new InvalidOperationException("Compare(DriftCurrentSnapshot, DriftBaselineSet) missing.");

            DriftCurrentContract orderContract = MakeCurrentContract("TestDomain.OrderProjection", "Orders", "Id");
            DriftBaselineContract orderBaseline = MakeBaselineContract("TestDomain.OrderProjection", "Orders", "Id");

            ImmutableArray<DriftCurrentContract> currentContracts;
            ImmutableArray<DriftCurrentContract> currentReversed;
            ImmutableArray<DriftBaselineContract> baselineContracts;
            ImmutableArray<DriftBaselineContract> baselineReversed;

            if (twoContracts) {
                // Story 9-1 review CB-2: real permutation requires ≥2 contracts (or members).
                // Use two distinct projections; reversing the array proves order independence.
                DriftCurrentContract shipContract = MakeCurrentContract("TestDomain.ShipmentProjection", "Shipping", "Priority");
                DriftBaselineContract shipBaseline = MakeBaselineContract("TestDomain.ShipmentProjection", "Shipping", "Priority");

                currentContracts = ImmutableArray.Create(orderContract, shipContract);
                currentReversed = ImmutableArray.Create(shipContract, orderContract);
                baselineContracts = ImmutableArray.Create(orderBaseline, shipBaseline);
                baselineReversed = ImmutableArray.Create(shipBaseline, orderBaseline);
            }
            else {
                currentContracts = ImmutableArray.Create(orderContract);
                currentReversed = currentContracts;
                baselineContracts = ImmutableArray.Create(orderBaseline);
                baselineReversed = baselineContracts;
            }

            return new InvocationProbe {
                CompareMethod = compare,
                SampleDomain = new DriftCurrentSnapshot(currentContracts),
                SampleBaseline = new DriftBaselineSet(baselineContracts),
                ReversedDomain = new DriftCurrentSnapshot(currentReversed),
                ReversedBaseline = new DriftBaselineSet(baselineReversed),
            };
        }

        private static DriftCurrentContract MakeCurrentContract(string type, string boundedContext, string propertyName)
            => new(
                "projection",
                type,
                boundedContext,
                displayName: null,
                displayGroupName: null,
                role: null,
                icon: null,
                destructive: null,
                requiresPolicy: null,
                emptyStateCtaCommandTypeName: null,
                ImmutableArray.Create(new DriftCurrentProperty(
                    propertyName,
                    "String",
                    false,
                    derivable: null,
                    displayName: null,
                    description: null,
                    columnPriority: null,
                    fieldGroup: null,
                    displayFormat: "Default",
                    relativeTimeWindowDays: null,
                    badgeSignature: null)),
                string.Empty,
                -1,
                -1);

        private static DriftBaselineContract MakeBaselineContract(string type, string boundedContext, string propertyName)
            => new(
                "frontcomposer.drift-baseline.json",
                "projection",
                type,
                boundedContext,
                displayName: null,
                displayGroupName: null,
                role: null,
                icon: null,
                destructive: null,
                requiresPolicy: null,
                emptyStateCtaCommandTypeName: null,
                ImmutableArray.Create(new DriftBaselineProperty(
                    propertyName,
                    "String",
                    false,
                    derivable: null,
                    displayName: null,
                    description: null,
                    columnPriority: null,
                    fieldGroup: null,
                    displayFormat: "Default",
                    relativeTimeWindowDays: null,
                    badgeSignature: null)));
    }
}

using System.Globalization;
using System.Reflection;
using System.Runtime.CompilerServices;
using System.Text.RegularExpressions;

using Hexalith.FrontComposer.Contracts.Diagnostics;
using Hexalith.FrontComposer.SourceTools.Diagnostics;

using Microsoft.CodeAnalysis;

using Shouldly;

namespace Hexalith.FrontComposer.SourceTools.Tests.Drift.Diagnostics;

/// <summary>
/// AC12 / T4 — Story 9-1 catalog discipline.
/// </summary>
public sealed class DriftDiagnosticCatalogTests {
    private const string DocsLinkPrefix = "https://hexalith.github.io/FrontComposer/diagnostics/";
    private const int FirstAllocatedDriftId = 1058;
    private const int LastReservedDriftId = 1099;

    [Fact]
    public void DriftDescriptors_AreContiguousFromHfc1058() {
        DiagnosticDescriptor[] driftDescriptors = [.. DriftDescriptors()];

        driftDescriptors.Length.ShouldBeGreaterThan(0,
            "AC12 — at least one drift descriptor must be allocated in T4.");
        int[] numericIds = [.. driftDescriptors.Select(d => int.Parse(d.Id["HFC".Length..], CultureInfo.InvariantCulture))];
        numericIds.Min().ShouldBeGreaterThanOrEqualTo(FirstAllocatedDriftId);
        numericIds.Max().ShouldBeLessThanOrEqualTo(LastReservedDriftId);

        // CH-15 — IDs must be unique.
        numericIds.Distinct().Count().ShouldBe(numericIds.Length,
            "AC12 / T4 — drift descriptor IDs must be unique.");

        // CM-10 — no gaps inside the allocated range.
        int[] sorted = [.. numericIds.OrderBy(n => n)];
        Enumerable.Range(sorted[0], sorted[^1] - sorted[0] + 1)
            .ShouldBe(sorted, ignoreOrder: false,
                "AC12 / T4 — drift IDs must be contiguous (no gaps in HFC1058+).");
    }

    [Fact]
    public void EveryDriftDescriptor_PopulatesHelpLinkUri_AgainstCanonicalDocsPrefix() {
        static Regex pathSegment(string id) => new($"/{Regex.Escape(id)}(/|$|\\.html|\\.md)", RegexOptions.CultureInvariant);

        foreach (DiagnosticDescriptor descriptor in DriftDescriptors()) {
            descriptor.HelpLinkUri.ShouldNotBeNullOrWhiteSpace($"AC12 — {descriptor.Id} missing HelpLinkUri.");
            descriptor.HelpLinkUri.ShouldStartWith(DocsLinkPrefix);
            // CM-4 — assert the ID appears as a path segment, not just any substring.
            pathSegment(descriptor.Id).IsMatch(descriptor.HelpLinkUri).ShouldBeTrue(
                $"AC12 — {descriptor.Id} HelpLinkUri must contain the ID as a path segment, got: {descriptor.HelpLinkUri}");
        }
    }

    [Fact]
    public void EveryDriftDescriptorId_HasMatchingFcDiagnosticIdsConstant() {
        HashSet<string> driftIds = [.. DriftDescriptors().Select(d => d.Id)];
        HashSet<string> constantIds = [.. typeof(FcDiagnosticIds)
            .GetFields(BindingFlags.Public | BindingFlags.Static)
            .Where(f => f.IsLiteral && f.FieldType == typeof(string))
            .Select(f => (string)f.GetRawConstantValue()!)
            .Where(v => v.StartsWith("HFC", StringComparison.Ordinal))];

        foreach (string driftId in driftIds) {
            constantIds.ShouldContain(driftId,
                $"AC12 / T4 — every drift descriptor must have a matching FcDiagnosticIds constant ({driftId}).");
        }
    }

    [Fact]
    public void EveryDriftDescriptor_IsDocumentedInUnshippedAnalyzerReleases() {
        string releasesPath = LocateAnalyzerReleasesUnshipped();
        string releaseNotes = File.ReadAllText(releasesPath);

        // CH-7 — assert each ID appears as a real release-notes row of shape:
        // `HFC#### | <Severity> | <Category> | <Notes>` rather than a comment-only mention.
        foreach (DiagnosticDescriptor descriptor in DriftDescriptors()) {
            Regex row = new($@"^\s*{Regex.Escape(descriptor.Id)}\s*\|", RegexOptions.Multiline);
            row.IsMatch(releaseNotes).ShouldBeTrue(
                $"AC12 / T4 — {descriptor.Id} must be listed in AnalyzerReleases.Unshipped.md as a `ID | Severity | Category | Notes` row.");
        }
    }

    [Fact]
    public void DriftDescriptors_HaveUniqueTitles() {
        // CH-14 — copy-paste regression where two descriptors share Title would ship silently.
        // MessageFormat is intentionally "{0}" across drift descriptors (Story 9-1 DEF-9-1A-3:
        // structured data flows through the diagnostic property bag), so duplicates there are
        // by-design and not asserted.
        DiagnosticDescriptor[] descriptors = [.. DriftDescriptors()];

        IEnumerable<IGrouping<string, DiagnosticDescriptor>> dupTitles = descriptors
            .GroupBy(d => d.Title.ToString(CultureInfo.InvariantCulture), StringComparer.Ordinal)
            .Where(g => g.Count() > 1);
        dupTitles.ShouldBeEmpty(
            "AC12 — drift descriptor Title values must be unique across descriptors.");
    }

    [Fact]
    public void Hfc1010_IsNotReusedByAnyDriftDescriptor() {
        // CC-3 — scan ALL DiagnosticDescriptors fields, not just the drift range, for any
        // descriptor sharing HFC1010's ID. The previous filter excluded HFC1010 by construction,
        // making the assertion tautological.
        IEnumerable<DiagnosticDescriptor> allDescriptors = AllSourceToolsDescriptors();
        int hfc1010Count = allDescriptors.Count(d => d.Id == FcDiagnosticIds.HFC1010_FullRebuildRequired);
        hfc1010Count.ShouldBe(1,
            "AC12 — HFC1010 is owned by Story 1-8 and must be allocated to exactly one descriptor (no drift reuse).");
    }

    [Fact]
    public void EveryHfcDescriptor_HasFourDigitNumericTail() {
        // CM-14 — mis-shaped IDs (e.g. HFC10A0) would slip through DriftDescriptors() filter.
        IEnumerable<DiagnosticDescriptor> hfcDescriptors = AllSourceToolsDescriptors()
            .Where(d => d.Id.StartsWith("HFC", StringComparison.Ordinal));

        foreach (DiagnosticDescriptor d in hfcDescriptors) {
            string tail = d.Id["HFC".Length..];
            (tail.Length == 4 && tail.All(char.IsDigit)).ShouldBeTrue(
                $"AC12 — descriptor {d.Id} must follow HFCxxxx shape with a 4-digit numeric tail.");
        }
    }

    private static IEnumerable<DiagnosticDescriptor> DriftDescriptors() {
        foreach (DiagnosticDescriptor descriptor in AllSourceToolsDescriptors()) {
            if (descriptor.Id.StartsWith("HFC", StringComparison.Ordinal)
                && int.TryParse(descriptor.Id.AsSpan("HFC".Length), NumberStyles.None, CultureInfo.InvariantCulture, out int n)
                && n >= FirstAllocatedDriftId
                && n <= LastReservedDriftId) {
                yield return descriptor;
            }
        }
    }

    private static IEnumerable<DiagnosticDescriptor> AllSourceToolsDescriptors() {
        foreach (FieldInfo field in typeof(DiagnosticDescriptors).GetFields(BindingFlags.Public | BindingFlags.Static)) {
            if (field.FieldType == typeof(DiagnosticDescriptor)
                && field.GetValue(null) is DiagnosticDescriptor descriptor) {
                yield return descriptor;
            }
        }
    }

    private static string LocateAnalyzerReleasesUnshipped([CallerFilePath] string callerPath = "") {
        // CM-1 — anchor at the test source location via [CallerFilePath] and walk up to repo root.
        string? dir = Path.GetDirectoryName(callerPath);
        while (dir is not null) {
            string candidate = Path.Combine(dir, "src", "Hexalith.FrontComposer.SourceTools", "AnalyzerReleases.Unshipped.md");
            if (File.Exists(candidate)) {
                return candidate;
            }

            dir = Path.GetDirectoryName(dir);
        }

        throw new FileNotFoundException("AnalyzerReleases.Unshipped.md not found from caller path: " + callerPath);
    }
}

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

using Shouldly;

using static Hexalith.FrontComposer.SourceTools.Tests.Drift.Comparison.DriftClassifierProjectionPropertyTests;

namespace Hexalith.FrontComposer.SourceTools.Tests.Drift.Diagnostics;

/// <summary>
/// AC12 / T4 — diagnostic contract. Each drift diagnostic must:
/// (a) carry a populated <see cref="DiagnosticDescriptor.HelpLinkUri"/>,
/// (b) expose all stable property keys (BaselinePath, DeclarationPath, DeclarationName,
///     MemberName, DriftKind, ExpectedShapeHash, ActualShapeHash, SchemaVersion, AlgorithmVersion),
/// (c) include the What/Expected/Got/Fix/DocsLink narrative shape in its message,
/// (d) normalize paths to repo-relative forward slashes or the &lt;outside-project&gt; sentinel.
/// </summary>
public sealed class DriftDiagnosticContractTests {
    private const string SkipReason = "RED-PHASE: T4 — drift diagnostic contract not yet introduced.";

    private static readonly string[] RequiredPropertyKeys = [
        "BaselinePath",
        "DeclarationPath",
        "DeclarationName",
        "MemberName",
        "DriftKind",
        "ExpectedShapeHash",
        "ActualShapeHash",
        "SchemaVersion",
        "AlgorithmVersion",
    ];

    private const string BaselineProjectionRemovedMember = """
        { "schemaVersion": "frontcomposer.generated-ui-baseline.v1",
          "algorithm": "frontcomposer-structural-v1",
          "contracts": [{ "family": "projection", "type": "TestDomain.OrderProjection", "boundedContext": "Orders",
            "properties": [
              { "name": "Id",      "category": "String", "nullable": false, "columnPriority": 0 },
              { "name": "Removed", "category": "String", "nullable": false, "columnPriority": 1 }
            ] }] }
        """;

    [Fact()]
    public void EveryDriftDiagnostic_CarriesPopulatedHelpLinkUri() {
        IReadOnlyList<Diagnostic> diagnostics = Run(SourceWithMissingMember(), BaselineProjectionRemovedMember);

        Diagnostic[] driftDiagnostics = [.. diagnostics.Where(d => d.Id.StartsWith("HFC10", StringComparison.Ordinal))];
        driftDiagnostics.Length.ShouldBeGreaterThan(0);
        foreach (Diagnostic d in driftDiagnostics) {
            d.Descriptor.HelpLinkUri.ShouldNotBeNullOrWhiteSpace($"AC12 — {d.Id} must populate HelpLinkUri.");
            d.Descriptor.HelpLinkUri.ShouldStartWith("https://hexalith.github.io/FrontComposer/diagnostics/");
        }
    }

    [Fact()]
    public void EveryDriftDiagnostic_ExposesAllRequiredPropertyKeys_OrSentinel() {
        IReadOnlyList<Diagnostic> diagnostics = Run(SourceWithMissingMember(), BaselineProjectionRemovedMember);

        Diagnostic[] driftDiagnostics = [.. diagnostics.Where(d => d.Id.StartsWith("HFC10", StringComparison.Ordinal))];
        driftDiagnostics.Length.ShouldBeGreaterThan(0);
        foreach (Diagnostic d in driftDiagnostics) {
            foreach (string key in RequiredPropertyKeys) {
                d.Properties.ContainsKey(key).ShouldBeTrue($"AC12 — {d.Id} missing property '{key}'.");
                // Absent values must use a fixed sentinel, never null/empty.
                d.Properties[key].ShouldNotBeNullOrWhiteSpace($"AC12 — {d.Id} property '{key}' must be a stable value or sentinel.");
            }
        }
    }

    [Fact()]
    public void DiagnosticMessage_HasWhatExpectedGotFixDocsLinkShape() {
        IReadOnlyList<Diagnostic> diagnostics = Run(SourceWithMissingMember(), BaselineProjectionRemovedMember);

        Diagnostic? drift = diagnostics.FirstOrDefault(d => d.Id.StartsWith("HFC10", StringComparison.Ordinal)
                                                         && d.GetMessage(System.Globalization.CultureInfo.InvariantCulture).Contains("Removed", StringComparison.Ordinal));
        _ = drift.ShouldNotBeNull();
        string message = drift!.GetMessage(System.Globalization.CultureInfo.InvariantCulture);
        // Story 9-1 review CB-6: AC12 enumerates "What, Expected, Got, Fix, and DocsLink fields".
        // Production templates do emit "What:" — assert it explicitly so a regression that drops
        // the leading What: clause is caught.
        message.ShouldContain("What", Case.Insensitive);
        message.ShouldContain("Expected", Case.Insensitive);
        message.ShouldContain("Got", Case.Insensitive);
        message.ShouldContain("Fix", Case.Insensitive);
        message.ShouldContain("https://hexalith.github.io/FrontComposer/diagnostics/", Case.Insensitive);
    }

    [Fact()]
    public void BaselinePathProperty_IsRepoRelativeForwardSlash_OrOutsideProjectSentinel() {
        IReadOnlyList<Diagnostic> diagnostics = Run(SourceWithMissingMember(), BaselineProjectionRemovedMember);

        Diagnostic[] driftDiagnostics = [.. diagnostics.Where(d => d.Id.StartsWith("HFC10", StringComparison.Ordinal))];
        foreach (Diagnostic d in driftDiagnostics) {
            string baselinePath = d.Properties["BaselinePath"]!;
            baselinePath.ShouldNotContain("\\", customMessage: "AC12 — BaselinePath must be forward-slash.");
            IsWindowsDriveRootedPath(baselinePath).ShouldBeFalse(
                "AC12 — BaselinePath must not leak a Windows drive-root absolute path.");
            (baselinePath == "<outside-project>" || !Path.IsPathRooted(baselinePath))
                .ShouldBeTrue("AC12 — BaselinePath must be repo-relative or the <outside-project> sentinel.");
        }
    }

    [Theory]
    [InlineData("fixtures/frontcomposer:drift-baseline.json", false)]
    [InlineData("C:/repo/frontcomposer.drift-baseline.json", true)]
    [InlineData("C:\\repo\\frontcomposer.drift-baseline.json", true)]
    [InlineData("C:repo/frontcomposer.drift-baseline.json", false)]
    public void WindowsDriveRootedPathCheck_AllowsBenignColonOnly(string path, bool expected) {
        _ = path.ShouldNotBeNull();
        IsWindowsDriveRootedPath(path).ShouldBe(expected);
    }

    [Fact()]
    public void DiagnosticLocation_PointsAtSourceDeclaration_NotBaselineFile() {
        IReadOnlyList<Diagnostic> diagnostics = Run(SourceWithMissingMember(), BaselineProjectionRemovedMember);

        Diagnostic[] driftDiagnostics = [.. diagnostics.Where(d => d.Id.StartsWith("HFC10", StringComparison.Ordinal)
                                                                && d.Location != Location.None)];
        driftDiagnostics.Length.ShouldBeGreaterThan(0);
        foreach (Diagnostic d in driftDiagnostics) {
            // Story 9-1 review P12: drift comparison no longer combines `CompilationProvider`
            // (so SyntaxTree-backed locations are not available without re-coupling), but the
            // diagnostic location still carries the C# file path via `GetMappedLineSpan().Path`.
            // Story 9-1 review CB-4: a path of `"baseline-stub.cs"` would slip past the
            // earlier `EndsWith(".cs")`-only check. Pin the path to the actual source file
            // (`Test0.cs` is the synthetic name produced by `CompilationHelper.CreateCompilation`)
            // and assert the line/column references the projection declaration position.
            Microsoft.CodeAnalysis.FileLinePositionSpan span = d.Location.GetMappedLineSpan();
            string path = span.Path;
            path.ShouldEndWith("Test0.cs",
                customMessage: "AC12 — diagnostic location must point at the source `.cs` file, not a baseline-side stub. Got: " + path);
            path.ShouldNotContain("baseline",
                customMessage: "AC12 — diagnostic location must NOT reference the baseline JSON.");
            // Synthetic test compilation produces declarations starting at line 0 (1-indexed: 1+).
            (span.StartLinePosition.Line >= 0).ShouldBeTrue("AC12 — location must carry a real line position.");
        }
    }

