            public partial class OrderProjection {
                public string Notes { get; set; } = string.Empty;
            }
            """;

        (string Hint, string Source)[] forward = RunAndCollectGenerated([partA, partB], ValidBaseline);
        (string Hint, string Source)[] reverse = RunAndCollectGenerated([partB, partA], ValidBaseline);

        AssertSameSetByHint(forward, reverse, "AC18 — partial-declaration order must not change generated bytes.");
    }

