namespace Hexalith.FrontComposer.SourceTools.Tests.Emitters;

/// <summary>
/// Story 2-3 Task 5.4 + 5.5 — bridge emitter tests (structure + determinism + snapshot).
/// </summary>
public class LifecycleBridgeEmitterTests {
    private static CommandFluxorModel BuildFluxor(
        string typeName = "IncrementCommand",
        string @namespace = "Counter.Domain") =>
        new(
            typeName,
            @namespace,
            typeName + "LifecycleState",
            typeName + "LifecycleFeature",
            typeName + "Actions",
            typeName + "Reducers",
            @namespace + "." + typeName,
            @namespace + "." + typeName + "LifecycleState");

    [Fact]
    public void Emit_CommandWithStandardActions_ProducesBridgeClassWithSixSubscriptions() {
        string source = CommandLifecycleBridgeEmitter.Emit(BuildFluxor());

        source.ShouldContain("public sealed class IncrementCommandLifecycleBridge : global::System.IDisposable");
        source.ShouldContain(".SubscribeToAction<IncrementCommandActions.SubmittedAction>");
        source.ShouldContain(".SubscribeToAction<IncrementCommandActions.AcknowledgedAction>");
        source.ShouldContain(".SubscribeToAction<IncrementCommandActions.SyncingAction>");
        source.ShouldContain(".SubscribeToAction<IncrementCommandActions.ConfirmedAction>");
        source.ShouldContain(".SubscribeToAction<IncrementCommandActions.RejectedAction>");
        source.ShouldContain(".SubscribeToAction<IncrementCommandActions.ResetToIdleAction>");
        source.ShouldContain("try { _subscriber.UnsubscribeFromAllActions(this); } catch { }");
    }

    [Fact]
    public void Emit_RejectedAction_ForwardsExactlyOneRejectedTransitionToLifecycleService() {
        string source = CommandLifecycleBridgeEmitter.Emit(BuildFluxor());

        source.ShouldContain("_subscriber.SubscribeToAction<IncrementCommandActions.RejectedAction>(this,");
        source.ShouldContain("a => ForwardAction(a.CorrelationId, global::Hexalith.FrontComposer.Contracts.Lifecycle.CommandLifecycleState.Rejected, null));");
        source.ShouldContain("_dispatcher.Dispatch(new IncrementCommandActions.RejectedAction(transition.CorrelationId");
    }

    [Fact]
    public void Emit_ResolverLifecycleTransitionsDispatchTerminalFluxorActionsWithoutFeedbackLoops() {
        string source = CommandLifecycleBridgeEmitter.Emit(BuildFluxor());

        source.ShouldContain("_service.Subscribe(correlationId, OnLifecycleTransition)");
        source.ShouldContain("_forwardingActions.ContainsKey((transition.CorrelationId, transition.NewState))");
        source.ShouldContain("Dictionary<(string CorrelationId, global::Hexalith.FrontComposer.Contracts.Lifecycle.CommandLifecycleState State), int>");
        source.ShouldContain("_dispatcher.Dispatch(new IncrementCommandActions.ConfirmedAction(transition.CorrelationId))");
        source.ShouldContain("_dispatcher.Dispatch(new IncrementCommandActions.RejectedAction(transition.CorrelationId");
        source.ShouldContain("_lifecycleSubscriptions.Remove(transition.CorrelationId, out terminalSubscription)");
        source.ShouldContain("terminalSubscription?.Dispose();");
        source.ShouldContain("RemoveLifecycleSubscriptionsExcept(action.CorrelationId)");
        source.ShouldContain("|| !_lifecycleSubscriptions.ContainsKey(transition.CorrelationId)) return;");
        source.ShouldContain("subscription?.Dispose();");
        source.ShouldContain("_lifecycleSubscriptions.Add(correlationId, null);");
        source.ShouldContain("if (disposeSubscription) { subscription.Dispose(); }");
        source.ShouldContain("catch (global::System.Exception exception) when (!IsFatal(exception))");
        source.ShouldContain("A stale subscription must not block the remaining sweep or the new submission.");
        source.ShouldContain("One failing Dispose must not leak the remaining subscriptions.");
        source.ShouldContain("exception is global::System.OutOfMemoryException");
        source.ShouldContain("exception is global::System.AggregateException aggregate");
        source.ShouldContain("global::System.Linq.Enumerable.Any(aggregate.Flatten().InnerExceptions, IsFatal)");
    }

    [Fact]
    public void Emit_CommandNamespace_MatchesCommand() {
        string source = CommandLifecycleBridgeEmitter.Emit(BuildFluxor("ConfigureCounterCommand", "Counter.Domain"));

        source.ShouldContain("namespace Counter.Domain;");
        source.ShouldContain("public sealed class ConfigureCounterCommandLifecycleBridge");
    }

    [Fact]
    public void Emit_DeterministicOutput_RunningTwiceProducesIdenticalSource() {
        CommandFluxorModel model = BuildFluxor();

        string first = CommandLifecycleBridgeEmitter.Emit(model);
        string second = CommandLifecycleBridgeEmitter.Emit(model);

        second.ShouldBe(first);
    }

    [Fact]
    public Task Emit_IncrementCommand() => Verify(CommandLifecycleBridgeEmitter.Emit(BuildFluxor()));

    [Fact]
    public Task Emit_ConfigureCounterCommand() =>
        Verify(CommandLifecycleBridgeEmitter.Emit(BuildFluxor("ConfigureCounterCommand", "Counter.Domain")));

    [Fact]
    public Task Emit_NestedNamespace() =>
        Verify(CommandLifecycleBridgeEmitter.Emit(BuildFluxor(
            "BulkIncrementCommand",
            "Counter.Domain.Batch.Operations")));
}

using System.Collections.Immutable;

using Hexalith.FrontComposer.SourceTools.Emitters;
using Hexalith.FrontComposer.SourceTools.Parsing;

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

using Shouldly;

namespace Hexalith.FrontComposer.SourceTools.Tests.Emitters;

public sealed class McpManifestEmitterTests {
    [Fact]
    public void Emit_LiteralEdgeCases_CompileAndRoundTripRuntimeConstants() {
        CancellationToken cancellationToken = TestContext.Current.CancellationToken;
        const string edge = "quote:\" slash:\\ controls:\0\a\b\f\n\r\t\v next:\u0085 line:\u2028 paragraph:\u2029";
        string inputLiteral = GeneratedLiteral.Escape(edge);
        string commandSource = $$"""
            using System.ComponentModel.DataAnnotations;
            using Hexalith.FrontComposer.Contracts.Attributes;

            namespace EdgeCases;

            [Command]
            [Display(Name = "{{inputLiteral}}", Description = "{{inputLiteral}}")]// Literal edge-case input.
            public partial class LiteralCommand {
                [Display(Name = "{{inputLiteral}}", Description = "{{inputLiteral}}")]// Literal edge-case input.
                public string Value { get; set; } = string.Empty;
            }
            """;
        CommandModel command = CompilationHelper.ParseCommand(commandSource, "EdgeCases.LiteralCommand").Model!;

        string generated = McpManifestEmitter.Emit(ImmutableArray.Create(command), []);
        CSharpCompilation compilation = CompilationHelper.CreateCompilation(generated);
        SyntaxTree tree = CSharpSyntaxTree.ParseText(generated, cancellationToken: cancellationToken);

        compilation.GetDiagnostics(cancellationToken)
            .Where(diagnostic => diagnostic.Severity == DiagnosticSeverity.Error)
            .ShouldBeEmpty("MCP manifest source with literal edge cases must compile.");
        tree.GetRoot(cancellationToken).DescendantTokens()
            .Where(token => token.IsKind(SyntaxKind.StringLiteralToken))
            .Select(token => token.ValueText)
            .ShouldContain(edge);
    }

    [Fact]
    public void Emit_CommandDescriptors_OnePerCommand_WithNamespaceDisambiguationForDuplicateBaseNames() {
        const string OrdersSource = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            using System.ComponentModel.DataAnnotations;
            namespace Orders;
            [Command]
            [BoundedContext("Sales")]
            [Display(Name = "Approve Order")]
            [RequiresPolicy("OrderApprover")]
            public partial class ApproveCommand {
                public string TenantId { get; set; } = "";
                public string UserId { get; set; } = "";
                public string MessageId { get; set; } = "";
                public string CommandId { get; set; } = "";
                public string CorrelationId { get; set; } = "";
                [Display(Name = "Order number")]
                public string OrderNumber { get; set; } = "";
            }
            """;
        const string BillingSource = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            namespace Billing;
            [Command]
            [BoundedContext("Sales")]
            public partial class ApproveCommand {
                public string MessageId { get; set; } = "";
                public decimal Amount { get; set; }
            }
            """;

        CommandModel orders = CompilationHelper.ParseCommand(OrdersSource, "Orders.ApproveCommand").Model!;
        CommandModel billing = CompilationHelper.ParseCommand(BillingSource, "Billing.ApproveCommand").Model!;

        string source = McpManifestEmitter.Emit(ImmutableArray.Create(orders, billing), []);

        source.Split("new McpCommandDescriptor(").Length.ShouldBe(3);
        source.ShouldContain("\"Sales.Orders.ApproveCommand.Execute\"");
        source.ShouldContain("\"Sales.Billing.ApproveCommand.Execute\"");
        source.ShouldContain("\"Orders.ApproveCommand\"");
        source.ShouldContain("\"Billing.ApproveCommand\"");
        source.ShouldContain("\"OrderApprover\"");
        source.ShouldContain("\"OrderNumber\"");
        source.ShouldContain("\"TenantId\"");
        source.ShouldContain("\"UserId\"");
        source.ShouldContain("\"MessageId\"");
        source.ShouldContain("\"CommandId\"");
        source.ShouldContain("\"CorrelationId\"");
        source.ShouldContain("new SchemaFingerprint(\"frontcomposer.schema.sha256.v1.sourcetools-blob\"");
        source.ShouldNotContain("\"Sales.ApproveCommand.Execute\"");
    }

    [Fact]
    public void Emit_ProjectionDescriptor_UsesTypedRenderStrategyLiteral() {
        const string Source = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            namespace Orders;
            [Projection]
            [BoundedContext("Sales")]
            [ProjectionRole(ProjectionRole.Timeline)]
            public partial class OrderTimelineProjection {
                public string Number { get; set; } = "";
            }
            """;

        DomainModel parsed = CompilationHelper.ParseProjection(Source, "Orders.OrderTimelineProjection").Model!;

        string source = McpManifestEmitter.Emit([], ImmutableArray.Create(parsed));

        source.ShouldContain("McpProjectionRenderStrategy.Timeline");
        source.ShouldNotContain("\"Timeline\",");
        // DN-2 / D23: SourceTools-emitted fingerprints declare a distinct algorithm id
        // because the build-time canonicalizer produces a key=value text blob (not JSON).
        source.ShouldContain("new SchemaFingerprint(\"frontcomposer.schema.sha256.v1.sourcetools-blob\"");
        source.ShouldContain("using Hexalith.FrontComposer.Contracts.Schema;");
    }
}

using System.Collections.Immutable;

using Hexalith.FrontComposer.SourceTools.Emitters;
using Hexalith.FrontComposer.SourceTools.Parsing;
using Hexalith.FrontComposer.SourceTools.Transforms;

using Microsoft.CodeAnalysis.CSharp;

using Shouldly;

namespace Hexalith.FrontComposer.SourceTools.Tests.Emitters;

/// <summary>
/// Story 4-2 T5.1 (AC1, AC3, D5, D8, D10, D14) — targeted unit coverage for
/// <see cref="ColumnEmitter.EmitColumn"/> badge-aware branches. The full end-to-end
/// emission paths are covered by the <c>RoleSpecificProjectionApprovalTests</c>
/// approval baselines; this file provides fast, focused assertions for the Story 1-5
/// regression gate and for the nullable / partial / Flags edge cases.
/// </summary>
public class RazorEmitterBadgeColumnTests {
    private static readonly EquatableArray<BadgeMappingEntry> _emptyBadges =
        new(ImmutableArray<BadgeMappingEntry>.Empty);
    private static readonly EquatableArray<string> _emptyEnumMembers =
        new(ImmutableArray<string>.Empty);

    /// <summary>
    /// Story 4-2 T5.3 + AC3 — regression gate. An enum column without any
    /// <c>[ProjectionBadge]</c> mapping must emit the byte-for-byte Story 1-5 text path
    /// with no badge ChildContent.
    /// </summary>
    [Fact]
    public void ZeroMappings_EmitsPlainTextPath_AndNoBadgeChildContent() {
        RazorModel model = new(
            "OrderProjection",
            "TestDomain",
            "Orders",
            new EquatableArray<ColumnModel>(ImmutableArray.Create(
                new ColumnModel("Status", "Status", TypeCategory.Enum, "Humanize:30", false, _emptyBadges, _emptyEnumMembers))));

        string source = RazorEmitter.Emit(model);

        source.ShouldContain("Truncate(HumanizeEnumLabel(x.Status.ToString()), 30)");
        source.ShouldNotContain("FcStatusBadge");
        source.ShouldNotContain("FcStatusIcon");
        // Story 4-5 amended: the expand-row chevron TemplateColumn introduces a
        // RenderFragment<OrderProjection> ChildContent on every Default emission, so the
        // unconditional negative-assert was relaxed to the badge-specific path. The badge
        // ChildContent always opens with `b.AddAttribute(colSeq++, "ChildContent",
        // (RenderFragment<OrderProjection>)(item => (RenderTreeBuilder rb) => { ... item.Status`.
        source.ShouldNotContain("item.Status.ToString() switch");
    }

    /// <summary>
    /// Story 4-2 AC3 / RF3 — partial coverage. Mapped enum members emit
    /// <c>FcStatusIcon</c> switch arms; declared-but-unannotated members emit plain-text
    /// arms that render the humanized label (partial coverage is an HFC1025 fallback, not
    /// an error); the <c>default</c> arm covers out-of-range runtime values (unsafe casts)
    /// with the localised <c>StatusBadgeUnknownStateFallback</c> resource lookup. Badge columns
    /// must use <c>TemplateColumn</c> because FluentUI <c>PropertyColumn</c> has no
    /// <c>ChildContent</c> parameter.
    /// </summary>
    [Fact]
    public void PartialMappings_EmitsSwitchWithBadgeArmsPlusTextDefault() {
        EquatableArray<BadgeMappingEntry> badges = new(ImmutableArray.Create(
            new BadgeMappingEntry("Pending", "Warning"),
            new BadgeMappingEntry("Approved", "Success")));
        EquatableArray<string> declaredMembers = new(ImmutableArray.Create("Pending", "Approved", "Cancelled"));

        RazorModel model = new(
            "OrderProjection",
            "TestDomain",
            "Orders",
            new EquatableArray<ColumnModel>(ImmutableArray.Create(
                new ColumnModel("Status", "Status", TypeCategory.Enum, "Humanize:30", false, badges, declaredMembers))));

        string source = RazorEmitter.Emit(model);

        RenderTreeSequenceRewriterTests.ShouldUseLiteralRenderTreeSequences(source);
        string masked = GeneratedRenderTreeText.MaskSequenceArguments(source);
        masked.ShouldContain("b.OpenComponent<TemplateColumn<OrderProjection>>(#);");
        masked.ShouldNotContain("b.OpenComponent<PropertyColumn<OrderProjection, string?>>(#);");
        source.ShouldContain("Hexalith.FrontComposer.Shell.Components.Badges.FcStatusIcon");
        source.ShouldNotContain("Hexalith.FrontComposer.Shell.Components.Badges.FcStatusBadge");
        source.ShouldContain("case \"Pending\":");
        source.ShouldContain("BadgeSlot.Warning");
        source.ShouldContain("case \"Approved\":");
        source.ShouldContain("BadgeSlot.Success");
        // Declared-but-unannotated member renders plain humanized text.
        source.ShouldContain("case \"Cancelled\":");
        source.ShouldContain("rb.AddContent(10, _label);");
        // Default arm uses the localised unknown-state fallback resource.
        source.ShouldContain("default:");
        source.ShouldContain("FcShellLocalizer[\"StatusBadgeUnknownStateFallback\"].Value");
    }

    /// <summary>
    /// Story 4-2 D8 / AC1 — nullable enum values render the em-dash fallback before any
    /// badge switch. Preserves the Story 1-5 "null is data-absence" convention.
    /// </summary>
    [Fact]
    public void NullableEnum_WithBadgeMappings_EmitsNullCheckBeforeSwitch() {
        EquatableArray<BadgeMappingEntry> badges = new(ImmutableArray.Create(
            new BadgeMappingEntry("Pending", "Warning")));

        RazorModel model = new(
            "OrderProjection",
            "TestDomain",
            "Orders",
            new EquatableArray<ColumnModel>(ImmutableArray.Create(
                new ColumnModel("Status", "Status", TypeCategory.Enum, "Humanize:30", true, badges, _emptyEnumMembers))));

        string source = RazorEmitter.Emit(model);

        source.ShouldContain("if (!item.Status.HasValue)");
        source.ShouldContain("rb.AddContent(0, \"\\u2014\");");
        source.ShouldContain("var _memberName = item.Status.Value.ToString();");
        source.ShouldContain("case \"Pending\":");
    }

    /// <summary>
    /// Story 4-2 D14 / AC1 — <c>HumanizeEnumLabel</c> is the label source for badges too,
    /// not a resource lookup. Guards against the "localise enum labels via resource keys"
    /// slip where a well-meaning refactor routes badge text through
    /// <see cref="Microsoft.Extensions.Localization.IStringLocalizer"/>. The generator still
    /// injects <c>IStringLocalizer&lt;FcShellResources&gt;</c> for the RF3 out-of-range
    /// fallback path — the assertion here is narrowly that the LABEL is never sourced from
    /// a localizer lookup (the assigned expression for <c>_label</c> stays on
    /// <c>HumanizeEnumLabel</c>).
    /// </summary>
    [Fact]
    public void BadgeLabelUsesHumanizeEnumLabel_NotResourceLookup() {
        EquatableArray<BadgeMappingEntry> badges = new(ImmutableArray.Create(
            new BadgeMappingEntry("Active", "Success")));

        RazorModel model = new(
            "OrderProjection",
            "TestDomain",
            "Orders",
            new EquatableArray<ColumnModel>(ImmutableArray.Create(
                new ColumnModel("Status", "Status", TypeCategory.Enum, "Humanize:30", false, badges, _emptyEnumMembers))));

        string source = RazorEmitter.Emit(model);

        source.ShouldContain("var _label = HumanizeEnumLabel(_memberName);");
        source.ShouldNotContain("_label = FcShellLocalizer[");
        source.ShouldNotContain("_label = Localizer[");
    }

    /// <summary>
    /// Story 4-2 AC5 — generated status-icon emission always threads the column header into the
    /// <c>ColumnHeader</c> parameter so adopter-side screen readers announce the contextual
    /// state, not a bare state name.
    /// </summary>
    [Fact]
    public void StatusIconEmission_SuppliesColumnHeaderForAriaLabelContext() {
        EquatableArray<BadgeMappingEntry> badges = new(ImmutableArray.Create(
            new BadgeMappingEntry("Active", "Success")));

        RazorModel model = new(
            "OrderProjection",
            "TestDomain",
            "Orders",
            new EquatableArray<ColumnModel>(ImmutableArray.Create(
                new ColumnModel("Status", "Order status", TypeCategory.Enum, "Humanize:30", false, badges, _emptyEnumMembers))));

        string source = RazorEmitter.Emit(model);

        source.ShouldContain("rb.AddAttribute(3, \"ColumnHeader\", \"Order status\");");
    }

    /// <summary>
    /// Story 4-2 — output must remain valid C# at every branch. Parses a badge-annotated
    /// emission through Roslyn and asserts no syntactic diagnostics.
    /// </summary>
    [Fact]
    public void BadgeEmission_ParsesAsValidCSharp() {
        CancellationToken ct = TestContext.Current.CancellationToken;
        EquatableArray<BadgeMappingEntry> badges = new(ImmutableArray.Create(
            new BadgeMappingEntry("Pending", "Warning"),
            new BadgeMappingEntry("Approved", "Success"),
            new BadgeMappingEntry("Rejected", "Danger")));

        RazorModel model = new(
            "OrderProjection",
            "TestDomain",
            "Orders",
            new EquatableArray<ColumnModel>(ImmutableArray.Create(
                new ColumnModel("Status", "Status", TypeCategory.Enum, "Humanize:30", true, badges, _emptyEnumMembers))));

        string source = RazorEmitter.Emit(model);
        Microsoft.CodeAnalysis.SyntaxTree tree = CSharpSyntaxTree.ParseText(source, cancellationToken: ct);
        tree.GetDiagnostics(ct).ShouldBeEmpty("Emitted badge code should parse without syntax errors");
    }
}

