    private static string GeneratedRoot(string consumer, string configuration)
        => Path.Combine(consumer, "obj", configuration, ConsumerTargetFramework, "generated");

    private static async Task VerifyConsumerConfigurationAsync(string consumer, string configuration) {
        await RunDotnetAsync(
            consumer,
            TestContext.Current.CancellationToken,
            "clean",
            "-c",
            configuration,
            "-m:1",
            "/nr:false").ConfigureAwait(true);

        // Start this leg from no emitted source at all. Anything found under the configuration's
        // own generated root afterwards must therefore come from this configuration's analyzer
        // run, so a passing leg can never be satisfied by the other leg's stale output.
        string generatedRoot = GeneratedRoot(consumer, configuration);
        if (Directory.Exists(generatedRoot)) {
            Directory.Delete(generatedRoot, recursive: true);
        }

        // Story 11.21 AC3/AC7 — the consumer template enables AnalysisMode=Recommended with
        // TreatWarningsAsErrors intact and no ASP0006 control, so each clean build independently
        // proves that packaged generated output is clean under the elevated policy.
        string buildLog = await RunDotnetAsync(
            consumer,
            TestContext.Current.CancellationToken,
            "build",
            "-c",
            configuration,
            "--no-incremental",
            "-m:1",
            "/nr:false").ConfigureAwait(true);
        CollectCaAspDiagnostics(buildLog).ShouldBeEmpty();

        Directory.Exists(generatedRoot).ShouldBeTrue(
            $"the packaged analyzer must emit {configuration} source into {generatedRoot}");
        string[] generatedFiles = Directory.GetFiles(
            generatedRoot,
            "*.cs",
            SearchOption.AllDirectories);
        generatedFiles.ShouldNotBeEmpty($"the packaged analyzer must emit {configuration} source in its isolated output");
        string projectionSourcePath = generatedFiles.Single(path => path.EndsWith("OrdersProjection.g.razor.cs", StringComparison.Ordinal));
        string projectionSource = await File.ReadAllTextAsync(projectionSourcePath, TestContext.Current.CancellationToken).ConfigureAwait(true);
        projectionSource.ShouldContain("global::Hexalith.FrontComposer.Shell.Options.FcShellOptions");
        projectionSource.ShouldContain("global::Hexalith.FrontComposer.Shell.State.DataGridNavigation.LoadPageAction");

        // Story 11.21 AC3 — packaged output must carry emitter-assigned literals, never a runtime
        // counter, and must not reintroduce the ASP0006 pragma the literals replaced.
        List<string> nonLiteralSequenceSites = [];
        foreach (string generatedFile in generatedFiles) {
            string generatedSource = await File.ReadAllTextAsync(generatedFile, TestContext.Current.CancellationToken).ConfigureAwait(true);
            generatedSource.ShouldNotContain("ASP0006");
            foreach (Match match in RuntimeSequenceArgumentPattern().Matches(generatedSource)) {
                nonLiteralSequenceSites.Add(Path.GetFileName(generatedFile) + ": " + match.Value);
            }
        }

        nonLiteralSequenceSites.ShouldBeEmpty();
        projectionSource.ShouldContain("BuildRenderTree");

        // Positive control: an injected CA1822 must surface under the template's Recommended mode and
        // stay silent under Default. An empty CA/ASP log alone cannot prove elevation is active —
        // NoWarn / Default would also produce an empty log.
        string probePath = Path.Combine(consumer, "Ca1822Probe.cs");
        try {
            await File.WriteAllTextAsync(probePath, """
namespace PackageConsumer;

public sealed class Ca1822Probe
{
    public string Describe() => "probe";
}
""", TestContext.Current.CancellationToken).ConfigureAwait(true);

            (int recommendedExit, string recommendedProbeLog) = await RunDotnetAllowingFailureAsync(
                consumer,
                TestContext.Current.CancellationToken,
                "build",
                "-c",
                configuration,
                "-m:1",
                "/nr:false").ConfigureAwait(true);
            recommendedExit.ShouldNotBe(0, $"injected CA1822 must fail the {configuration} Recommended + TWAE consumer build");
            CollectCaAspDiagnostics(recommendedProbeLog)
                .ShouldContain(static line => line.Contains("CA1822", StringComparison.Ordinal));

            (int defaultExit, string defaultProbeLog) = await RunDotnetAllowingFailureAsync(
                consumer,
                TestContext.Current.CancellationToken,
                "build",
                "-c",
                configuration,
                "-m:1",
                "/nr:false",
                "-p:AnalysisMode=Default").ConfigureAwait(true);
            defaultExit.ShouldBe(0, $"the same {configuration} CA1822 probe must stay silent under AnalysisMode=Default");
            CollectCaAspDiagnostics(defaultProbeLog)
                .ShouldNotContain(static line => line.Contains("CA1822", StringComparison.Ordinal));
        }
        finally {
            File.Delete(probePath);
        }
    }

    /// <summary>
    /// Matches a <c>RenderTreeBuilder</c> call whose sequence argument is a runtime counter
    /// increment rather than an emitter-assigned literal. Optional whitespace before <c>++</c>
    /// is included so a leftover <c>seq ++</c> cannot bypass the packaged gate.
    /// </summary>
    [GeneratedRegex(
        @"\.(?:OpenElement|OpenComponent|AddAttribute|AddContent|AddMarkupContent|OpenRegion|AddMultipleAttributes|AddElementReferenceCapture|AddComponentReferenceCapture)(?:<[^(]*>)?\(\s*[A-Za-z_][A-Za-z0-9_]*\s*\+\+",
        RegexOptions.CultureInvariant)]
    private static partial Regex RuntimeSequenceArgumentPattern();

    private static string[] CollectCaAspDiagnostics(string buildLog)
        => [.. buildLog
            .Split('\n')
            .Select(static line => line.Trim())
            .Where(static line => line.Contains(": warning CA", StringComparison.Ordinal)
                || line.Contains(": error CA", StringComparison.Ordinal)
                || line.Contains(": warning ASP", StringComparison.Ordinal)
                || line.Contains(": error ASP", StringComparison.Ordinal))];

    private static string FindRepoRoot() {
        DirectoryInfo? directory = new(AppContext.BaseDirectory);
        while (directory is not null) {
            if (File.Exists(Path.Combine(directory.FullName, "Hexalith.FrontComposer.slnx"))) {
                return directory.FullName;
            }

            directory = directory.Parent;
        }

        throw new InvalidOperationException("Could not locate repository root.");
    }

    private static void AssertCentralPackageVersion(string root, string packageId, string expectedVersion) {
        string path = Path.Combine(root, "references", "Hexalith.Builds", "Props", "Directory.Packages.props");
        XDocument document = XDocument.Load(path);
        string? actualVersion = document
            .Descendants("PackageVersion")
            .Single(element => string.Equals((string?)element.Attribute("Include"), packageId, StringComparison.Ordinal))
            .Attribute("Version")
            ?.Value;

        actualVersion.ShouldBe(expectedVersion);
    }

    private static void AssertPackageDependencyVersion(string packageOutput, string packageId, string dependencyId, string expectedVersion) {
        string package = Directory.GetFiles(packageOutput, $"{packageId}.*.nupkg").Single();
        using ZipArchive archive = ZipFile.OpenRead(package);
        ZipArchiveEntry nuspec = archive.Entries.Single(entry => entry.FullName.EndsWith(".nuspec", StringComparison.Ordinal));
        using Stream stream = nuspec.Open();
        XDocument document = XDocument.Load(stream);
        string actualVersion = document
            .Descendants()
            .Where(element => string.Equals(element.Name.LocalName, "dependency", StringComparison.Ordinal))
            .Where(element => string.Equals((string?)element.Attribute("id"), dependencyId, StringComparison.Ordinal))
            .Select(element => (string?)element.Attribute("version"))
            .Distinct(StringComparer.Ordinal)
            .Single()!;

        actualVersion.ShouldBe(expectedVersion);
    }

    private static async Task<string> RunDotnetAsync(string workingDirectory, CancellationToken cancellationToken, params string[] args) {
        (int exitCode, string log) = await RunDotnetAllowingFailureAsync(workingDirectory, cancellationToken, args).ConfigureAwait(true);
        if (exitCode != 0) {
            throw new InvalidOperationException(
                $"dotnet {string.Join(' ', args)} failed with exit code {exitCode}.{Environment.NewLine}{log}");
        }

        return log;
    }

    private static async Task<(int ExitCode, string Log)> RunDotnetAllowingFailureAsync(
        string workingDirectory,
        CancellationToken cancellationToken,
        params string[] args) {
        ProcessStartInfo startInfo = new("dotnet") {
            WorkingDirectory = workingDirectory,
            RedirectStandardError = true,
            RedirectStandardOutput = true,
        };
        foreach (string arg in args) {
            startInfo.ArgumentList.Add(arg);
        }

        using Process process = Process.Start(startInfo)
            ?? throw new InvalidOperationException("Failed to start dotnet.");
        string stdout = await process.StandardOutput.ReadToEndAsync(cancellationToken).ConfigureAwait(true);
        string stderr = await process.StandardError.ReadToEndAsync(cancellationToken).ConfigureAwait(true);
        await process.WaitForExitAsync(cancellationToken).ConfigureAwait(true);

        return (process.ExitCode, stdout + Environment.NewLine + stderr);
    }
}

