            firstField,
            firstMethod);
        _ = metadata.AddTypeDefinition(
            TypeAttributes.Public | TypeAttributes.Class,
            metadata.GetOrAddString("MetadataFixtures"),
            metadata.GetOrAddString("Bad-Type"),
