namespace Hexalith.FrontComposer.SourceTools.Tests.Transforms;

public sealed class Level1FormatTransformTests {
    private static readonly EquatableArray<BadgeMappingEntry> EmptyBadges = new(ImmutableArray<BadgeMappingEntry>.Empty);

    [Fact]
    public void Transform_RelativeTimeFormat_CarriesUiAgnosticColumnMetadata() {
        RazorModel model = RazorModelTransform.Transform(Model(Prop("LastChanged", "DateTime", FieldDisplayFormat.RelativeTime)));

        model.Columns[0].DisplayFormat.ShouldBe(FieldDisplayFormat.RelativeTime);
        model.Columns[0].FormatHint.ShouldBe("RelativeTime");
        model.Columns[0].RelativeTimeWindowDays.ShouldBe(7);
    }

    [Fact]
    public void Transform_CurrencyFormat_CarriesColumnMetadataAndKeepsNumericCategory() {
        RazorModel model = RazorModelTransform.Transform(Model(Prop("Amount", "Decimal", FieldDisplayFormat.Currency)));

        model.Columns[0].DisplayFormat.ShouldBe(FieldDisplayFormat.Currency);
        model.Columns[0].TypeCategory.ShouldBe(TypeCategory.Numeric);
        model.Columns[0].FormatHint.ShouldBe("C");
    }

    [Fact]
    public void Transform_DisplayNameStillWins_WhenFormatAnnotationIsPresent() {
        RazorModel model = RazorModelTransform.Transform(Model(
            Prop("LastChanged", "DateTime", FieldDisplayFormat.RelativeTime, displayName: "Last changed")));

        model.Columns[0].Header.ShouldBe("Last changed");
    }

    [Fact]
    public void Transform_FormatOverride_DoesNotChangePrioritySortOrder() {
        RazorModel model = RazorModelTransform.Transform(Model(
            Prop("Unannotated", "String"),
            Prop("Amount", "Decimal", FieldDisplayFormat.Currency, priority: 2),
            Prop("LastChanged", "DateTime", FieldDisplayFormat.RelativeTime, priority: 1)));

        model.Columns.Select(c => c.PropertyName).ShouldBe(["LastChanged", "Amount", "Unannotated"]);
    }

    // ──────────────────────────────────────────────────────────────────────────
    //   Story 6-1 review F19 / T1 — story-owned regression for the pre-existing
    //   ColumnPriority semantics (lower-first, unannotated → int.MaxValue,
    //   declaration-order tiebreak). Locks the Story 4-4 contract through the
    //   Story 6-1 ParseDisplayFormat changes so a future refactor that drops
    //   priority sorting on Level 1 columns cannot regress silently.
    // ──────────────────────────────────────────────────────────────────────────

    [Fact]
    public void Transform_UnannotatedPriority_SortsAfterAnnotatedPriorities() {
        RazorModel model = RazorModelTransform.Transform(Model(
            Prop("UnannotatedA", "String"),
            Prop("Annotated", "String", priority: 100),
            Prop("UnannotatedB", "String")));

        // Lower priority is earlier; unannotated → int.MaxValue, so they sort after.
        model.Columns.Select(c => c.PropertyName).ShouldBe(["Annotated", "UnannotatedA", "UnannotatedB"]);
    }

    [Fact]
    public void Transform_PriorityExtremes_MinValueSortsFirstMaxValueLast() {
        RazorModel model = RazorModelTransform.Transform(Model(
            Prop("Mid", "String", priority: 0),
            Prop("Pinned", "String", priority: int.MinValue),
            Prop("LastExplicit", "String", priority: int.MaxValue - 1)));

        model.Columns.Select(c => c.PropertyName).ShouldBe(["Pinned", "Mid", "LastExplicit"]);
    }

    [Fact]
    public void Transform_EqualPriority_PreservesDeclarationOrder() {
        RazorModel model = RazorModelTransform.Transform(Model(
            Prop("First", "String", priority: 1),
            Prop("Second", "String", priority: 1),
            Prop("Third", "String", priority: 1)));

        model.Columns.Select(c => c.PropertyName).ShouldBe(["First", "Second", "Third"]);
    }

    // ──────────────────────────────────────────────────────────────────────────
    //   Story 6-1 review F24 / T1 / T10 — story-owned regression for the
    //   Display.Name / [Description] / Display.Description precedence chain
    //   that Level 1 promises to preserve.
    // ──────────────────────────────────────────────────────────────────────────

    [Fact]
    public void Transform_DisplayNameOverridesHumanizedPropertyName() {
        RazorModel model = RazorModelTransform.Transform(Model(
            Prop("CustomerName", "String", displayName: "Recipient")));

        model.Columns[0].Header.ShouldBe("Recipient");
    }

    [Fact]
    public void Transform_PropertyName_HumanizesWhenDisplayNameAbsent() {
        RazorModel model = RazorModelTransform.Transform(Model(
            Prop("CustomerName", "String")));

        // Default header should NOT be the raw camelCase name; it must be humanized.
        model.Columns[0].Header.ShouldBe("Customer Name");
    }

    private static DomainModel Model(params PropertyModel[] props)
        => new("TestProjection", "TestDomain", "Test", null, null, new EquatableArray<PropertyModel>(props.ToImmutableArray()));

    private static PropertyModel Prop(
        string name,
        string typeName,
        FieldDisplayFormat displayFormat = FieldDisplayFormat.Default,
        string? displayName = null,
        int? priority = null)
        => new(
            name,
            typeName,
            isNullable: false,
            isUnsupported: false,
            displayName,
            EmptyBadges,
            columnPriority: priority,
            displayFormat: displayFormat);
}

using System.Collections.Immutable;

using Hexalith.FrontComposer.SourceTools.Parsing;
using Hexalith.FrontComposer.SourceTools.Transforms;

using Shouldly;

namespace Hexalith.FrontComposer.SourceTools.Tests.Transforms;

/// <summary>
/// Story 2.5 AC2 — pins the Transform-stage column ORDER produced by the
/// <c>(Priority ?? int.MaxValue, declarationOrder)</c> stable sort in
/// <see cref="RazorModelTransform"/>. The pre-existing emitter pin
/// (<c>RazorEmitterColumnPrioritizerTests.DescriptorListContainsAllColumnKeys</c>) asserts every
/// key is PRESENT, not that the descriptor list is ORDERED, and
/// <see cref="RazorModelTransformTests"/> carries no priority test — so a regression that dropped
/// the index-stable tiebreaker or stopped gating on <c>anyPriority</c> would pass every existing
/// test. These pins close that gap by asserting the resulting <see cref="ColumnModel"/> order
/// directly at the transform level (isolated from the &gt;15-col prioritizer wrap).
/// </summary>
[Trait("Category", "MutationErrorHandling")]
public class RazorModelColumnPriorityOrderTests {
    private static readonly EquatableArray<BadgeMappingEntry> _emptyBadges = new(ImmutableArray<BadgeMappingEntry>.Empty);

    [Fact]
    public void Transform_MixedPrioritiesAndUnannotated_AnnotatedAscendThenUnannotatedTrailInDeclarationOrder() {
        // Declared B(prio 2), A(none), C(prio 1) → expect C, B, A:
        // annotated ascend by priority (C=1, B=2); unannotated (A) trails via the int.MaxValue
        // sentinel, keeping declaration order among unannotated.
        RazorModel result = RazorModelTransform.Transform(Model(
            Prop("B", priority: 2),
            Prop("A"),
            Prop("C", priority: 1)));

        result.Columns.Count.ShouldBe(3);
        result.Columns[0].PropertyName.ShouldBe("C");
        result.Columns[1].PropertyName.ShouldBe("B");
        result.Columns[2].PropertyName.ShouldBe("A");
    }

    [Fact]
    public void Transform_MultipleUnannotatedTrailing_KeepDeclarationOrderAmongThemselves() {
        // High(prio 5), then three unannotated U1, U2, U3 → High first, then U1, U2, U3 in
        // declaration order (all share the int.MaxValue sentinel; the index tiebreaker holds).
        RazorModel result = RazorModelTransform.Transform(Model(
            Prop("High", priority: 5),
            Prop("U1"),
            Prop("U2"),
            Prop("U3")));

        result.Columns.Count.ShouldBe(4);
        result.Columns[0].PropertyName.ShouldBe("High");
        result.Columns[1].PropertyName.ShouldBe("U1");
        result.Columns[2].PropertyName.ShouldBe("U2");
        result.Columns[3].PropertyName.ShouldBe("U3");
    }

    [Fact]
    public void Transform_NoColumnDeclaresPriority_PreservesDeclarationOrderByteForByte() {
        // NO-OP gate: when NOT a single column declares a priority, the sort is skipped entirely
        // and declaration order is preserved verbatim — the CounterProjectionApprovalTests
        // invariant. Asserted explicitly so a regression that ALWAYS sorts is caught here.
        RazorModel result = RazorModelTransform.Transform(Model(
            Prop("Zebra"),
            Prop("Apple"),
            Prop("Mango")));

        result.Columns.Count.ShouldBe(3);
        result.Columns[0].PropertyName.ShouldBe("Zebra");
        result.Columns[1].PropertyName.ShouldBe("Apple");
        result.Columns[2].PropertyName.ShouldBe("Mango");

        // And the carried priorities are all null (no sentinel materialised onto the model).
        result.Columns[0].Priority.ShouldBeNull();
        result.Columns[1].Priority.ShouldBeNull();
        result.Columns[2].Priority.ShouldBeNull();
    }

    [Fact]
    public void Transform_TwoColumnsShareSamePriority_KeepDeclarationOrderViaIndexTiebreaker() {
        // Stability on collision: First(prio 1) and Second(prio 1) share the explicit value;
        // the index tiebreaker keeps their declaration order. Last(prio 2) sorts after both.
        RazorModel result = RazorModelTransform.Transform(Model(
            Prop("First", priority: 1),
            Prop("Last", priority: 2),
            Prop("Second", priority: 1)));

        result.Columns.Count.ShouldBe(3);
        result.Columns[0].PropertyName.ShouldBe("First");
        result.Columns[1].PropertyName.ShouldBe("Second");
        result.Columns[2].PropertyName.ShouldBe("Last");
    }

    [Fact]
    public void Transform_SignedEdgePriorities_MinValuePinsToFront_MaxValueSortsAmongUnannotated() {
        // int.MinValue pins to the very front; an explicit int.MaxValue is numerically equal to
        // the unannotated sentinel, so it interleaves with unannotated columns by declaration
        // order (the tiebreaker), proving the sort is a plain signed-int compare with no special
        // casing beyond the null→MaxValue projection.
        RazorModel result = RazorModelTransform.Transform(Model(
            Prop("Unannotated"),
            Prop("Front", priority: int.MinValue),
            Prop("Back", priority: int.MaxValue),
            Prop("Mid", priority: 0)));

        result.Columns.Count.ShouldBe(4);
        result.Columns[0].PropertyName.ShouldBe("Front"); // int.MinValue
        result.Columns[1].PropertyName.ShouldBe("Mid");   // 0
        // "Unannotated" (sentinel MaxValue, index 0) precedes "Back" (explicit MaxValue, index 2).
        result.Columns[2].PropertyName.ShouldBe("Unannotated");
        result.Columns[3].PropertyName.ShouldBe("Back");
    }

    private static DomainModel Model(params PropertyModel[] props)
        => new("TestProjection", "TestDomain", "Test", null, null, new EquatableArray<PropertyModel>(props.ToImmutableArray()));

    private static PropertyModel Prop(string name, int? priority = null)
        => new(name, "String", isNullable: false, isUnsupported: false, displayName: null, badgeMappings: _emptyBadges, columnPriority: priority);
}

using System.Collections.Immutable;

using Hexalith.FrontComposer.SourceTools.Parsing;
using Hexalith.FrontComposer.SourceTools.Transforms;

using Shouldly;

namespace Hexalith.FrontComposer.SourceTools.Tests.Transforms;

/// <summary>
/// Story 4-1 T2.6 — <see cref="RazorModelTransform"/> role → strategy mapping +
/// <c>WhenStates</c> CSV split + HFC1023 Dashboard dispatch + HFC1024 unknown-value
/// fallback. Full Exhaustiveness discipline per ADR-052.
/// </summary>
public class RazorModelRoleStrategyTests {
    [Theory]
    [InlineData("ActionQueue", ProjectionRenderStrategy.ActionQueue)]
    [InlineData("StatusOverview", ProjectionRenderStrategy.StatusOverview)]
    [InlineData("DetailRecord", ProjectionRenderStrategy.DetailRecord)]
    [InlineData("Timeline", ProjectionRenderStrategy.Timeline)]
    [InlineData("Dashboard", ProjectionRenderStrategy.Dashboard)]
    public void MapsAllKnownRoleNames(string role, ProjectionRenderStrategy expected) {
        DomainModel model = BuildDomainModel(role);

        RazorModel razor = RazorModelTransform.Transform(model);

        razor.Strategy.ShouldBe(expected);
    }

    [Fact]
    public void NullDomainRoleMapsToDefault() {
        DomainModel model = BuildDomainModel(null);

        RazorModel razor = RazorModelTransform.Transform(model);

        razor.Strategy.ShouldBe(ProjectionRenderStrategy.Default);
    }

    [Fact]
    public void EmptyDomainRoleMapsToDefault() {
        DomainModel model = BuildDomainModel(string.Empty);

        RazorModel razor = RazorModelTransform.Transform(model);

        razor.Strategy.ShouldBe(ProjectionRenderStrategy.Default);
    }

    [Fact]
    [Trait("Category", "MutationErrorRegression")]
    public void UnknownRoleValueMapsToDefault() {
        // D15 — if Parse ever delivered a non-enum role string (or a numeric payload
        // following an unsafe cast), Transform falls back to Default. HFC1024 already
        // emitted at Parse.
        DomainModel model = BuildDomainModel("999");

        RazorModel razor = RazorModelTransform.Transform(model);

        razor.Strategy.ShouldBe(ProjectionRenderStrategy.Default);
    }

    [Fact]
    public void WhenStateCsvIsSplitAndTrimmed() {
        DomainModel model = BuildDomainModel("ActionQueue", whenState: " Pending , Submitted , ");

        RazorModel razor = RazorModelTransform.Transform(model);

        string[] whenStates = [.. razor.WhenStates];
        whenStates.ShouldBe(["Pending", "Submitted"]);
    }

    [Fact]
    public void EmptyWhenStateYieldsEmptyArray() {
        DomainModel model = BuildDomainModel("ActionQueue", whenState: null);

        RazorModel razor = RazorModelTransform.Transform(model);

        razor.WhenStates.Count.ShouldBe(0);
    }

    [Fact]
    public void DashboardRoleEmitsHFC1023() {
        // D16 — HFC1023 Information emitted once per Dashboard projection per compilation.
        DomainModel model = BuildDomainModel("Dashboard");
        List<DiagnosticInfo> diagnostics = [];

        _ = RazorModelTransform.Transform(model, diagnostics);

        DiagnosticInfo[] hfc1023 = [.. diagnostics.Where(d => d.Id == "HFC1023")];
        hfc1023.Length.ShouldBe(1);
        hfc1023[0].Severity.ShouldBe("Info");
        hfc1023[0].Message.ShouldContain("Test");
    }

    [Fact]
    public void NonDashboardRolesDoNotEmitHFC1023() {
        DomainModel actionQueue = BuildDomainModel("ActionQueue");
        DomainModel defaultRole = BuildDomainModel(null);
        List<DiagnosticInfo> diagnostics = [];

        _ = RazorModelTransform.Transform(actionQueue, diagnostics);
        _ = RazorModelTransform.Transform(defaultRole, diagnostics);

        diagnostics.ShouldNotContain(d => d.Id == "HFC1023");
    }

    [Fact]
    public void WhenStatesAndStrategyParticipateInEquality() {
        // T1.7 cache-parity cornerstone — editing WhenState / role produces a DIFFERENT
        // RazorModel so the incremental-generator cache invalidates.
        RazorModel a = RazorModelTransform.Transform(BuildDomainModel("ActionQueue", whenState: "Pending"));
        RazorModel b = RazorModelTransform.Transform(BuildDomainModel("ActionQueue", whenState: "Pending,Submitted"));
        RazorModel c = RazorModelTransform.Transform(BuildDomainModel("Timeline", whenState: "Pending"));

        a.Equals(b).ShouldBeFalse();
        a.Equals(c).ShouldBeFalse();
        a.Equals(RazorModelTransform.Transform(BuildDomainModel("ActionQueue", whenState: "Pending")))
            .ShouldBeTrue();
    }

    [Fact]
    public void TwoIndependentTransformsOfIdenticalSourceProduceEqualModels() {
        // Round 4 per Winston — guards EquatableArray<T>.Equals against reference-equality
        // regression. Two independent transforms of identical input must yield equal models
        // AND equal hash codes.
        DomainModel domain = BuildDomainModel("ActionQueue", whenState: "Pending,Submitted");

        RazorModel m1 = RazorModelTransform.Transform(domain);
        RazorModel m2 = RazorModelTransform.Transform(domain);

        m1.Equals(m2).ShouldBeTrue();
        m1.GetHashCode().ShouldBe(m2.GetHashCode());
    }

    private static DomainModel BuildDomainModel(string? role, string? whenState = null) => new(
            "Test",
            "TestDomain",
            null,
            null,
            role,
            new EquatableArray<PropertyModel>(ImmutableArray<PropertyModel>.Empty),
            whenState);
}

