using System.Globalization;

using Hexalith.FrontComposer.SourceTools.Transforms;

using Shouldly;

namespace Hexalith.FrontComposer.SourceTools.Tests.Transforms;

/// <summary>
/// AC11 / T8 — two clean generations of the same domain source must produce byte-for-byte
/// identical fingerprints across OS / culture / TZ / EOL / path-separator combinations. The
/// canonicalizer's normalizer (line endings, Unicode line separators, trim) and ordering
/// (StringComparer.Ordinal) is the contract under test.
/// </summary>
public sealed class SchemaFingerprintDeterminismTests {
    [Theory]
    [InlineData("en-US")]
    [InlineData("tr-TR")] // dotted-i / dotless-i lowercase quirk
    [InlineData("de-DE")]
    [InlineData("ja-JP")]
    public void LifecyclePayload_FingerprintIdenticalAcrossCultures(string cultureName) {
        // 8-6a review H13: compute the invariant-culture fingerprint OUTSIDE the test culture
        // scope so the comparison actually crosses culture boundaries. The prior test computed
        // both sides under the same culture and passed vacuously.
        CultureInfo previousCulture = CultureInfo.CurrentCulture;
        CultureInfo previousUiCulture = CultureInfo.CurrentUICulture;

        CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;
        CultureInfo.CurrentUICulture = CultureInfo.InvariantCulture;
        string invariantFingerprint = SchemaFingerprintTransform.CreateLifecycleResultPayload().Fingerprint.Value;

        try {
            CultureInfo.CurrentCulture = CultureInfo.GetCultureInfo(cultureName);
            CultureInfo.CurrentUICulture = CultureInfo.GetCultureInfo(cultureName);

            string testCultureFingerprint = SchemaFingerprintTransform.CreateLifecycleResultPayload().Fingerprint.Value;
            string repeated = SchemaFingerprintTransform.CreateLifecycleResultPayload().Fingerprint.Value;

            testCultureFingerprint.ShouldBe(repeated, $"culture {cultureName} produced drift across two clean generations.");
            testCultureFingerprint.ShouldBe(
                invariantFingerprint,
                $"AC11 cross-culture invariant: fingerprint under {cultureName} must match invariant culture.");
        }
        finally {
            CultureInfo.CurrentCulture = previousCulture;
            CultureInfo.CurrentUICulture = previousUiCulture;
        }
    }

    [Theory]
    [InlineData("\n")]
    [InlineData("\r\n")]
    [InlineData("\r")]
    [InlineData("\u2028")] // Unicode LINE SEPARATOR
    [InlineData("\u2029")] // Unicode PARAGRAPH SEPARATOR
    public void RendererPayload_NormalizesEolInRendererId(string eol) {
        ArgumentNullException.ThrowIfNull(eol);
        // 8-6a review H12: actually inject the EOL into a string that flows through Normalize().
        // The prior test parameterized by `eol` but never used it in the payload inputs, so the
        // two computed fingerprints were trivially identical (same input, different parameter).
        // The renderer's `rendererId` is one of the strings that goes through Normalize, so a
        // multi-line value carrying any EOL flavor should canonicalize identically and produce
        // the same fingerprint.
        const string LfId = "frontcomposer.mcp.markdown\nextra";
        string variantId = "frontcomposer.mcp.markdown" + eol + "extra";

        string reference = SchemaFingerprintTransform.CreateMarkdownRendererPayload(
            LfId,
            "Default",
            maxCharacters: 64_000,
            maxFieldCharacters: 4_096).Fingerprint.Value;
        string variant = SchemaFingerprintTransform.CreateMarkdownRendererPayload(
            variantId,
            "Default",
            maxCharacters: 64_000,
            maxFieldCharacters: 4_096).Fingerprint.Value;

        variant.ShouldBe(
            reference,
            $"AC11: EOL '{eol.Replace("\r", "\\r").Replace("\n", "\\n")}' must canonicalize to the LF reference fingerprint.");
    }

    [Theory]
    [InlineData("\n")]
    [InlineData("\r\n")]
    [InlineData("\r")]
    [InlineData("\u2028")] // Unicode LINE SEPARATOR
    [InlineData("\u2029")] // Unicode PARAGRAPH SEPARATOR
    public void CommandPayload_NormalizesEolInParameterDescription(string eol) {
        ArgumentNullException.ThrowIfNull(eol);
        // 8-6a chunk-3 review (Edge F1+F8): exercises the FieldLine cell path where Normalize
        // runs AFTER per-cell EscapeDelimited (`SchemaFingerprintTransform.cs:241`). Pre-fix, a
        // U+2028 in a parameter Description survived EscapeDelimited and was then collapsed to a
        // bare `\n` by Normalize, splitting the canonical-blob row mid-cell and synthesizing a
        // fake `field=...` line. Post-fix, EscapeDelimited maps U+2028/U+2029 to the same `\\n`
        // escape as `\n` so all line-break flavors hash identically AND cannot inject rows.
        const string LfDescription = "first line\nsecond line";
        string variantDescription = "first line" + eol + "second line";

        McpCommandDescriptorModel reference = BuildCommand(LfDescription);
        McpCommandDescriptorModel variant = BuildCommand(variantDescription);

        string referenceFingerprint = SchemaFingerprintTransform.CreateCommandPayload(reference).Fingerprint.Value;
        string variantFingerprint = SchemaFingerprintTransform.CreateCommandPayload(variant).Fingerprint.Value;

        variantFingerprint.ShouldBe(
            referenceFingerprint,
            $"AC11: EOL '{eol.Replace("\r", "\\r").Replace("\n", "\\n")}' inside a parameter Description must canonicalize to the LF reference fingerprint.");
    }

    private static McpCommandDescriptorModel BuildCommand(string parameterDescription)
        => new(
            protocolName: "frontcomposer.test.command",
            commandTypeName: "Hexalith.FrontComposer.Tests.TestCommand",
            boundedContext: "Test",
            title: "Test Command",
            description: "command description",
            authorizationPolicyName: null,
            parameters: [
                new McpParameterDescriptorModel(
                    name: "Subject",
                    typeName: "string",
                    jsonType: "string",
                    isRequired: true,
                    isNullable: false,
                    title: "Subject",
                    description: parameterDescription,
                    enumValues: [],
                    isUnsupported: false),
            ],
            derivablePropertyNames: []);
}

using Hexalith.FrontComposer.Contracts.Schema;
using Hexalith.FrontComposer.SourceTools.Transforms;

using Shouldly;

namespace Hexalith.FrontComposer.SourceTools.Tests.Transforms;

/// <summary>
/// AC9 / T6 — derive lifecycle and renderer fingerprint material from runtime model structure
/// rather than literal field-list constants. The cross-package check that compares the
/// SourceTools-side lifecycle catalog against the Mcp-side <c>McpLifecycleResult</c> runtime
/// type lives in <c>tests/Hexalith.FrontComposer.Mcp.Tests/Schema/SchemaFingerprintCrossPackageTests.cs</c>
/// (8-6a Group B D10 resolution) so the cross-check rides Mcp's existing reference seam to
/// SourceTools rather than piercing Mcp's internal boundary from this test project.
/// </summary>
public sealed class SchemaFingerprintReflectionTests {
    [Fact]
    public void RendererPayload_BoundsContributeToFingerprint() {
        // AC9 behavior test: replaces the prior source-walking test (M10 — source walks broke
        // under packaged test runs). Different bounds must produce different fingerprints; if
        // the renderer payload ever stops consuming the bounds parameters (e.g. reverts to magic
        // numbers), this fails.
        GeneratedSchemaPayload first = SchemaFingerprintTransform.CreateMarkdownRendererPayload(
            "frontcomposer.mcp.markdown", "Auto", maxCharacters: 50_000, maxFieldCharacters: 1_000);
        GeneratedSchemaPayload second = SchemaFingerprintTransform.CreateMarkdownRendererPayload(
            "frontcomposer.mcp.markdown", "Auto", maxCharacters: 80_000, maxFieldCharacters: 2_000);

        first.Fingerprint.Value.ShouldNotBe(
            second.Fingerprint.Value,
            "AC9: renderer bounds must drive the fingerprint material.");
    }

    [Fact]
    public void LifecyclePayload_FingerprintIsStable_AcrossInvocations() {
        GeneratedSchemaPayload first = SchemaFingerprintTransform.CreateLifecycleResultPayload();
        GeneratedSchemaPayload second = SchemaFingerprintTransform.CreateLifecycleResultPayload();

        first.Fingerprint.Value.ShouldBe(second.Fingerprint.Value);
        // CK4-P9: per D23 / chunk-2 C1, lifecycle payload runs through the SourceTools blob
        // canonicalizer at build time. Pin to Sha256SourceToolsBlobV1 so a regression that swaps
        // canonicalizer (e.g. accidental use of Sha256CanonicalJsonV1) fails this test instead of
        // silently passing the prior `ShouldBeOneOf(...)` either-or.
        first.Fingerprint.AlgorithmId.ShouldBe(
            SchemaFingerprintAlgorithm.Sha256SourceToolsBlobV1,
            "D23: lifecycle payload must be canonicalized via the SourceTools blob algorithm; the runtime cannot recompute it (Roslyn analyzer hosting constraint).");
    }
}

using Hexalith.FrontComposer.SourceTools.Parsing;
using Hexalith.FrontComposer.SourceTools.Transforms;

using Shouldly;

namespace Hexalith.FrontComposer.SourceTools.Tests.Transforms;

[Trait("Category", "MutationErrorHandling")]
public sealed class SchemaFingerprintTransformTests {
    [Fact]
    public void CommandFingerprint_ChangesWhenStructuralFieldChanges_AndIgnoresRuntimeNames() {
        const string Source = """
            using Hexalith.FrontComposer.Contracts.Attributes;
            using System.ComponentModel.DataAnnotations;
            namespace Orders;
            [Command]
            [BoundedContext("Sales")]
            [Display(Name = "Approve Order")]
            public partial class ApproveOrderCommand {
                public string MessageId { get; set; } = "";
                public string TenantId { get; set; } = "";
                [Display(Name = "Order number")]
                public string OrderNumber { get; set; } = "";
            }
            """;

        CommandModel parsed = CompilationHelper.ParseCommand(Source, "Orders.ApproveOrderCommand").Model!;
        McpCommandDescriptorModel descriptor = McpManifestTransform.TransformCommand(parsed);
        GeneratedSchemaPayload payload = SchemaFingerprintTransform.CreateCommandPayload(descriptor);
        McpCommandDescriptorModel changed = new(
            descriptor.ProtocolName,
            descriptor.CommandTypeName,
            descriptor.BoundedContext,
            "Approve Purchase Order",
            descriptor.Description,
            descriptor.AuthorizationPolicyName,
            descriptor.Parameters,
            descriptor.DerivablePropertyNames);

        payload.Fingerprint.Value.ShouldNotBe(SchemaFingerprintTransform.CreateCommandPayload(changed).Fingerprint.Value);
        payload.Json.ShouldNotContain("TenantId");
        payload.Json.ShouldNotContain("MessageId");
    }

    [Fact]
    public void ResourceFingerprint_IsIndependentOfFieldEnumerationOrder() {
        var fieldA = new McpParameterDescriptorModel("Number", "String", "string", true, false, "Number", null, [], false);
        var fieldB = new McpParameterDescriptorModel("Status", "Enum", "string", true, false, "Status", null, ["Pending", "Approved"], false);
        var left = new McpResourceDescriptorModel(
            "frontcomposer://Sales/projections/OrderQueue",
            "OrderQueue",
            "Orders.OrderQueueProjection",
            "Sales",
            "Order queue",
            null,
            [fieldA, fieldB]);
        var right = new McpResourceDescriptorModel(
            left.ProtocolUri,
            left.Name,
            left.ProjectionTypeName,
            left.BoundedContext,
            left.Title,
            left.Description,
            [fieldB, fieldA]);

        SchemaFingerprintTransform.CreateResourcePayload(left).Fingerprint.Value
            .ShouldBe(SchemaFingerprintTransform.CreateResourcePayload(right).Fingerprint.Value);
    }

    [Fact]
    public void AggregateFingerprint_ChangesWhenNestedFingerprintChanges() {
        GeneratedSchemaFingerprint a = new(SchemaFingerprintTransform.AlgorithmId, new string('a', 64), SchemaFingerprintTransform.CanonicalizerVersion, SchemaFingerprintTransform.TestVectorId);
        GeneratedSchemaFingerprint b = new(SchemaFingerprintTransform.AlgorithmId, new string('b', 64), SchemaFingerprintTransform.CanonicalizerVersion, SchemaFingerprintTransform.TestVectorId);

        GeneratedSchemaFingerprint one = SchemaFingerprintTransform.CreateAggregateManifestPayload([a], [], null, [], []).Fingerprint;
        GeneratedSchemaFingerprint two = SchemaFingerprintTransform.CreateAggregateManifestPayload([b], [], null, [], []).Fingerprint;

        one.Value.ShouldNotBe(two.Value);
    }
}

using System.Collections.Immutable;

using Hexalith.FrontComposer.SourceTools.Parsing;
using Hexalith.FrontComposer.SourceTools.Transforms;

using Shouldly;

namespace Hexalith.FrontComposer.SourceTools.Tests.Transforms;

[Trait("Category", "MutationErrorHandling")]
public sealed class UnsupportedColumnEmissionTests {
    private static readonly EquatableArray<BadgeMappingEntry> EmptyBadges = new(ImmutableArray<BadgeMappingEntry>.Empty);

    [Fact]
    public void Transform_UnsupportedProperty_ProducesUnsupportedColumn() {
        RazorModel result = RazorModelTransform.Transform(Model(Unsupported("Metadata", "System.Collections.Generic.Dictionary<string, System.Collections.Generic.List<Tag>>")));

        result.Columns.Count.ShouldBe(1);
        result.Columns[0].PropertyName.ShouldBe("Metadata");
        result.Columns[0].Header.ShouldBe("Metadata");
        result.Columns[0].TypeCategory.ShouldBe(TypeCategory.Unsupported);
    }

    [Fact]
    public void Transform_MixedSupportedAndUnsupportedProperties_PreservesDeclarationOrder() {
        RazorModel result = RazorModelTransform.Transform(Model(
            Prop("Id", "Guid"),
            Prop("Status", "Enum"),
            Unsupported("Metadata", "System.Collections.Generic.Dictionary<string, string>")));

        result.Columns.Count.ShouldBe(3);
        result.Columns.Select(c => c.PropertyName).ShouldBe(["Id", "Status", "Metadata"]);
    }

    [Fact]
    public void Transform_PrioritySort_UnsupportedColumnWithNullPriority_SinksAfterPrioritizedColumn() {
        RazorModel result = RazorModelTransform.Transform(Model(
            Unsupported("Metadata", "System.Collections.Generic.Dictionary<string, string>"),
            Prop("Name", "String", priority: 1)));

        result.Columns.Select(c => c.PropertyName).ShouldBe(["Name", "Metadata"]);
        result.Columns[1].Priority.ShouldBeNull();
        result.Columns[1].TypeCategory.ShouldBe(TypeCategory.Unsupported);
    }

    [Fact]
    public void Transform_UnsupportedProperty_FieldGroupFlowsThrough() {
        RazorModel result = RazorModelTransform.Transform(Model(Unsupported(
            "Metadata",
            "System.Collections.Generic.Dictionary<string, string>",
            fieldGroup: "Metadata")));

        result.Columns[0].FieldGroup.ShouldBe("Metadata");
    }

    [Fact]
    public void Transform_UnsupportedProperty_DoesNotSupportFiltering() {
        RazorModel result = RazorModelTransform.Transform(Model(Unsupported("Metadata", "System.Collections.Generic.Dictionary<string, string>")));

        result.Columns[0].SupportsFilter.ShouldBeFalse();
    }

    private static DomainModel Model(params PropertyModel[] props)
        => new("TestProjection", "TestDomain", "Test", null, null, new EquatableArray<PropertyModel>(props.ToImmutableArray()));

    private static PropertyModel Prop(string name, string typeName, int? priority = null)
        => new(
            name,
            typeName,
            isNullable: false,
            isUnsupported: false,
            displayName: null,
            EmptyBadges,
            columnPriority: priority);

    private static PropertyModel Unsupported(string name, string typeName, string? fieldGroup = null)
        => new(
            name,
            typeName,
            isNullable: false,
            isUnsupported: true,
            displayName: null,
            EmptyBadges,
            unsupportedTypeFullyQualifiedName: typeName,
            fieldGroup: fieldGroup);
}
